# builder/gen_ch24_p1.py
# -*- coding: utf-8 -*-

exercises = [{'num': 1, 'title': 'Простейший синхронный TCP Echo-сервер на net.Listen и net.Conn', 'task': '**Простейший TCP Echo-сервер**: Напишите программу, которая слушает порт `8080` по протоколу TCP с помощью `net.Listen`. При подключении клиента сервер должен войти в бесконечный цикл, считывать входящие данные и отправлять их обратно клиенту (эхо). Закройте соединение, когда клиент отключится.', 'theory': 'Сетевой фундамент Go: пакет `net` инкапсулирует системные сокеты операционной системы. Метод `net.Listen("tcp", addr)` выполняет системные вызовы `socket()`, `bind()` и `listen()`, возвращая интерфейс `net.Listener`. Метод `listener.Accept()` блокирует выполнение до появления нового входящего TCP-соединения (3-Way Handshake SYN, SYN-ACK, ACK), возвращая двунаправленный поток `net.Conn` (`io.ReadWriteCloser`).', 'step_by_step': '1. Создадим слушатель `listener, err := net.Listen("tcp", "127.0.0.1:0")` (динамический порт для тестов).\n2. Запустим серверную горутину с циклом `Accept()`.\n3. Считываем данные в цикле `conn.Read(buf)` до получения `io.EOF`.\n4. Записываем прочитанные байты обратно в `conn.Write(buf[:n])`.\n5. Проверим передачу эхо-сообщения от тестового клиента.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net"\n\t"time"\n)\n\nfunc runEchoServer(listener net.Listener) {\n\tdefer listener.Close()\n\n\tfor {\n\t\tconn, err := listener.Accept()\n\t\tif err != nil {\n\t\t\treturn // Слушатель закрыт\n\t\t}\n\n\t\t// Обработка одного соединения\n\t\tfunc(c net.Conn) {\n\t\t\tdefer c.Close()\n\t\t\tbuf := make([]byte, 1024)\n\t\t\tfor {\n\t\t\t\tn, err := c.Read(buf)\n\t\t\t\tif err != nil {\n\t\t\t\t\tif err != io.EOF {\n\t\t\t\t\t\tfmt.Printf("[Server] Ошибка чтения: %v\\n", err)\n\t\t\t\t\t}\n\t\t\t\t\treturn // Клиент отключился\n\t\t\t\t}\n\t\t\t\t// Отправляем эхо обратно клиенту\n\t\t\t\t_, _ = c.Write(buf[:n])\n\t\t\t}\n\t\t}(conn)\n\t}\n}\n\nfunc main() {\n\t// Слушаем локальный TCP сокет на динамическом свободном порту\n\tlistener, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tserverAddr := listener.Addr().String()\n\tfmt.Printf("[Server] TCP Echo-сервер слушает адрес %s\\n", serverAddr)\n\n\tgo runEchoServer(listener)\n\n\t// Клиентское подключение для проверки\n\ttime.Sleep(10 * time.Millisecond)\n\tconn, err := net.Dial("tcp", serverAddr)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\tmsg := "Привет, TCP Сокет!"\n\t_, _ = conn.Write([]byte(msg))\n\n\treply := make([]byte, 1024)\n\tn, _ := conn.Read(reply)\n\n\tfmt.Printf("[Client] Отправлено: %s\\n", msg)\n\tfmt.Printf("[Client] Получено эхо: %s\\n", string(reply[:n]))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] TCP Echo-сервер слушает адрес 127.0.0.1:41235\n# [Client] Отправлено: Привет, TCP Сокет!\n# [Client] Получено эхо: Привет, TCP Сокет!'}], 'under_the_hood': 'В Go все сетевые сокеты переводятся в неблокирующий режим (`O_NONBLOCK`). Когда горутина вызывает `conn.Read()`, рантайм передает дескриптор в `netpoller` (под капотом `epoll` на Linux, `kqueue` на macOS). Горутина засыпает без блокировки потока ОС и мгновенно просыпается по готовности сетевого события.', 'pitfalls': 'Никогда не забывайте проверять ошибку `io.EOF`: когда удаленный хост закрывает сокет (`close()`), `conn.Read()` возвращает `0, io.EOF`. Попытка игнорировать `io.EOF` приведет к 100% загрузке CPU в бесконечном цикле.', 'bigtech_interview': '**Вопрос с собеседования:** «Как устроен сетевой Netpoller в Go рантайме?»\n**Ответ:** Netpoller — это подсистема рантайма Go, интегрированная с системными мультиплексорами ввода-вывода (epoll/kqueue/IOCP). Она отслеживает готовность дескрипторов сокетов и переводит ожидающие горутины из состояния `_Gwaiting` в очередь готовых к исполнению `_Grunnable` без создания системных тредов под каждое сетевое соединение.'}, {'num': 2, 'title': 'Интерактивный TCP Echo-сервер с циклом Accept и клиентом net.Dial', 'task': '**TCP-сервер (Echo)**: Используй `net.Listen("tcp", ":8080")`. Напиши цикл, который принимает подключения (`Accept()`). При подключении читай данные из соединения и отправляй их обратно клиенту (эхо). (Для теста используй утилиту `telnet` или `nc` в консоли).', 'theory': 'Архитектура TCP Client-Server: Сервер регистрирует сокет в ОС через `net.Listen`, а клиент инициирует установление TCP сессии вызовом `net.Dial("tcp", hostPort)`. Полнодуплексный канал позволяет обеим сторонам независимо передавать байты.', 'step_by_step': '1. Создадим TCP Listener.\n2. В цикле `for` вызываем `listener.Accept()`.\n3. Читаем входящие байты порциями и зеркально отправляем назад.\n4. Проверим обмен 3 тестовыми сообщениями.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net"\n\t"time"\n)\n\nfunc startEchoService(l net.Listener) {\n\tfor {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\n\t\tgo func(c net.Conn) {\n\t\t\tdefer c.Close()\n\t\t\tbuf := make([]byte, 512)\n\t\t\tfor {\n\t\t\t\tn, err := c.Read(buf)\n\t\t\t\tif err != nil {\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\t_, _ = c.Write(buf[:n])\n\t\t\t}\n\t\t}(conn)\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo startEchoService(l)\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент отправляет 3 запроса подряд\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\tcommands := []string{"PING\\n", "GET_STATUS\\n", "BYE\\n"}\n\tbuf := make([]byte, 512)\n\n\tfor _, cmd := range commands {\n\t\t_, _ = conn.Write([]byte(cmd))\n\t\tn, _ := conn.Read(buf)\n\t\tfmt.Printf("[Client] Sent: %q -> Echo Received: %q\\n", cmd, string(buf[:n]))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Sent: "PING\\n" -> Echo Received: "PING\\n"\n# [Client] Sent: "GET_STATUS\\n" -> Echo Received: "GET_STATUS\\n"\n# [Client] Sent: "BYE\\n" -> Echo Received: "BYE\\n" '}], 'under_the_hood': 'Вызов `net.Dial` выполняет `connect()` системный вызов ядра ОС, отправляя TCP SYN пакет и согласуя начальные Sequence Numbers (ISN) и размер скользящего окна (Window Size).', 'pitfalls': 'В сетевых приложениях `net.Conn` нельзя закрывать дважды, но `defer conn.Close()` защищает от утечки дескрипторов при любом завершении горутины.', 'bigtech_interview': '**Вопрос с собеседования:** «Какое максимальное число одновременных TCP-соединений может удерживать сервер на одном порту?»\n**Ответ:** Лимитируется не портом сервера, а 4-кортежем `(SrcIP, SrcPort, DstIP, DstPort)`, системным лимитом файловых дескрипторов `ulimit -n` и оперативной памятью под буферы сокетов `tcp_rmem`/`tcp_wmem` (на Linux — сотни тысяч и миллионы соединений при C1000K тюнинге).'}, {'num': 3, 'title': 'Построчный TCP-эхо-сервер с префиксом на базе bufio.Reader', 'task': 'Напиши **TCP-эхо-сервер**: `net.Listen("tcp", ":8080")`, принимай соединение `Accept()`, читай строку через `bufio.Reader`, пиши её обратно с префиксом `"Echo: "`. Закрой соединение после одного ответа.', 'theory': "Построчный протокол передачи данных: потоковый TCP не имеет границ сообщений. Для текстовых протоколов (SMTP, Redis RESP, IRC) используют разделитель строк `\\n`. Структура `bufio.Reader` буферизует поток байт и предоставляет метод `ReadString('\\n')`, считывающий данные строго до символа новой строки.", 'step_by_step': '1. Создадим TCP Listener.\n2. При подключении создадим `reader := bufio.NewReader(conn)`.\n3. Прочитаем строку через `line, err := reader.ReadString(\'\\n\')`.\n4. Отправим ответ `"Echo: " + line` и закроем сокет.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"time"\n)\n\nfunc runPrefixServer(l net.Listener) {\n\tfor {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\n\t\tgo func(c net.Conn) {\n\t\t\tdefer c.Close()\n\n\t\t\treader := bufio.NewReader(c)\n\t\t\tline, err := reader.ReadString(\'\\n\')\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\n\t\t\t// Пишем ответ с префиксом\n\t\t\treply := fmt.Sprintf("Echo: %s", line)\n\t\t\t_, _ = c.Write([]byte(reply))\n\t\t}(conn)\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo runPrefixServer(l)\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\t_, _ = conn.Write([]byte("Golang Highload Networking\\n"))\n\n\tresp, _ := bufio.NewReader(conn).ReadString(\'\\n\')\n\tfmt.Printf("[Client Response] %s", resp)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client Response] Echo: Golang Highload Networking'}], 'under_the_hood': '`bufio.Reader` держит внутренний буфер (по умолчанию 4096 байт), минимизируя количество системных вызовов `read()` к ядру ОС.', 'pitfalls': "Если вредоносный клиент отправит гигабайтный поток байт без символа `\\n`, `ReadString('\\n')` выделит гигабайт памяти в куче, вызвав OOM. Для безопасности ограничивают чтение через `io.LimitReader`.", 'bigtech_interview': "**Вопрос с собеседования:** «В чем опасность использования bufio.Reader.ReadString('\\\\n') в публичном сетевом сервисе?»\n**Ответ:** Риск DoS-атаки переполнением памяти (Unbounded Memory Allocation). Злоумышленник может непрерывно слать байты без символа `\\n`, из-за чего буфер будет расти до полного исчерпания RAM сервера."}, {'num': 4, 'title': 'Сырой низкоуровневый TCP HTTP-клиент с ручным формированием GET-запроса', 'task': 'Напишите TCP-клиент, который подключается к `google.com:80`, отправляет сырой HTTP GET-запрос (просто строку) и читает ответ.', 'theory': 'Протокол HTTP поверх чистого TCP: HTTP/1.1 является текстовым протоколом прикладного уровня (Layer 7), работающим поверх транспортного TCP (Layer 4). Ручная отправка RFC-совместимой строки `GET / HTTP/1.1\\r\\nHost: ...\\r\\nConnection: close\\r\\n\\r\\n` демонстрирует взаимодействие уровней сетевой модели OSI.', 'step_by_step': '1. Запустим локальный мок HTTP/1.1 сервера на чистом TCP-сокете.\n2. Клиент подключается через `net.Dial("tcp", addr)`.\n3. Отправляет сырую текстовую строку с HTTP-заголовками и `\\r\\n\\r\\n`.\n4. Считывает статусный HTTP-ответ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"strings"\n\t"time"\n)\n\n// Мок HTTP-сервера на чистом TCP сокете\nfunc runRawHTTPServer(l net.Listener) {\n\tfor {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\n\t\tgo func(c net.Conn) {\n\t\t\tdefer c.Close()\n\t\t\tscanner := bufio.NewScanner(c)\n\n\t\t\t// Читаем HTTP заголовки до пустой строки\n\t\t\tfor scanner.Scan() {\n\t\t\t\tif scanner.Text() == "" {\n\t\t\t\t\tbreak\n\t\t\t\t}\n\t\t\t}\n\n\t\t\t// Возвращаем сырой HTTP ответ\n\t\t\thttpResponse := "HTTP/1.1 200 OK\\r\\n" +\n\t\t\t\t"Content-Type: text/plain; charset=utf-8\\r\\n" +\n\t\t\t\t"Connection: close\\r\\n\\r\\n" +\n\t\t\t\t"Hello from Raw TCP HTTP Engine!"\n\t\t\t_, _ = c.Write([]byte(httpResponse))\n\t\t}(conn)\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo runRawHTTPServer(l)\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Сырой TCP-клиент\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\t// Формируем сырой HTTP/1.1 запрос\n\trawRequest := fmt.Sprintf("GET / HTTP/1.1\\r\\nHost: %s\\r\\nConnection: close\\r\\n\\r\\n", l.Addr().String())\n\t_, _ = conn.Write([]byte(rawRequest))\n\n\t// Читаем сырой ответ\n\treader := bufio.NewReader(conn)\n\tstatusLine, _ := reader.ReadString(\'\\n\')\n\tfmt.Printf("[Raw HTTP Client] Статусная строка: %s", statusLine)\n\n\tfor {\n\t\tline, err := reader.ReadString(\'\\n\')\n\t\tif err != nil {\n\t\t\tbreak\n\t\t}\n\t\tif strings.TrimSpace(line) == "" {\n\t\t\t// Настало тело ответа\n\t\t\tbreak\n\t\t}\n\t}\n\n\tbody, _ := reader.ReadString(\'\\n\')\n\tfmt.Printf("[Raw HTTP Client] Тело ответа: %s\\n", body)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Raw HTTP Client] Статусная строка: HTTP/1.1 200 OK\n# [Raw HTTP Client] Тело ответа: Hello from Raw TCP HTTP Engine!'}], 'under_the_hood': 'Разделитель `\\r\\n\\r\\n` (CRLF CRLF) согласно спецификации RFC 7230 отделяет HTTP-заголовки от тела полезной нагрузки (Payload).', 'pitfalls': 'В UNIX средах перевод строки — `\\n`, но в стандартах интернет-протоколов (HTTP, SMTP, FTP) обязателен `\\r\\n` (Carriage Return + Line Feed).', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем в HTTP/1.1 обязателен заголовок Host, если IP-адрес уже указан при TCP-подключении?»\n**Ответ:** Для Virtual Hosting (SNI): на одном физическом IP-адресе и порту 80/443 могут работать тысячи независимых веб-сайтов, и сервер определяет нужный виртуальный хост именно по заголовку `Host`.'}, {'num': 5, 'title': 'TCP-сервер однократного приветствия (Banner Server)', 'task': 'Создайте TCP-сервер на `localhost:8080`, который принимает соединения и отправляет «Hello, client!» каждому подключившемуся.', 'theory': 'Паттерн Greeting/Banner Server: сразу после установления TCP-сессии сервер отправляет приветственное сообщение (Banner) и закрывает соединение или переходит в режим ожидания команд.', 'step_by_step': '1. Создадим слушатель `net.Listen`.\n2. При `listener.Accept()` немедленно отправляем сообщение `Hello, client!\\n`.\n3. Закрываем соединение `conn.Close()`.\n4. Проверим получение приветствия клиентом.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"time"\n)\n\nfunc runGreetingServer(l net.Listener) {\n\tfor {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\n\t\tgo func(c net.Conn) {\n\t\t\tdefer c.Close()\n\t\t\t_, _ = c.Write([]byte("Hello, client!\\n"))\n\t\t}(conn)\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo runGreetingServer(l)\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\tgreeting, _ := bufio.NewReader(conn).ReadString(\'\\n\')\n\tfmt.Printf("[Client] Получено приветствие от сервера: %s", greeting)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Получено приветствие от сервера: Hello, client!'}], 'under_the_hood': 'Закрытие `conn.Close()` инициирует отправку TCP FIN пакета, завершая сессию 4-ступенчатым рукопожатием.', 'pitfalls': 'Если клиент не успеет вызвать `conn.Read()` до закрытия сокета сервером, в ОС может возникнуть ошибка `connection reset by peer` при наличии неотправленных данных.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое TCP 4-Way Handshake при закрытии соединения?»\n**Ответ:** 1. Клиент/сервер шлет `FIN`; 2. Вторая сторона отвечает `ACK`; 3. Вторая сторона шлет свой `FIN`; 4. Инициатор закрытия отвечает `ACK` и переходит в состояние `TIME_WAIT` на $2 \\times \\text{MSL}$.'}, {'num': 6, 'title': 'Масштабируемый многопоточный TCP-сервер: горутина на каждое соединение', 'task': 'Модифицируй сервер из 15.1: обрабатывай каждое соединение в **отдельной горутине**. Сервер должен принимать множество клиентов одновременно без блокировки.', 'theory': 'Модель «Горутина на соединение» (Goroutine-per-Connection): в отличие от C/C++ (где на 10 000 клиентов требовался сложный event-loop на epoll), в Go легковесные горутины (стек от 2 КБ) позволяют запускать отдельный линейный обработчик `go handle(conn)` на каждое активное соединение.', 'step_by_step': '1. Создадим `net.Listener`.\n2. В цикле `Accept()` вызываем `go handleClient(conn)`.\n3. Подключим 5 параллельных клиентов одновременно.\n4. Убедимся в параллельной неблокирующей обработке.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"sync"\n\t"time"\n)\n\nfunc handleClient(conn net.Conn, clientID int) {\n\tdefer conn.Close()\n\tbuf := make([]byte, 256)\n\tn, err := conn.Read(buf)\n\tif err != nil {\n\t\treturn\n\t}\n\n\treply := fmt.Sprintf("ACK: [%s] (обратно клиенту #%d)", string(buf[:n]), clientID)\n\t_, _ = conn.Write([]byte(reply))\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\t// Сервер\n\tgo func() {\n\t\tid := 0\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tid++\n\t\t\t// КАНОНИЧЕСКИЙ ПАТТЕРН GO: горутина на каждое новое соединение!\n\t\t\tgo handleClient(conn, id)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Запуск 3 параллельных клиентов\n\tvar wg sync.WaitGroup\n\tconst totalClients = 3\n\twg.Add(totalClients)\n\n\tfor i := 1; i <= totalClients; i++ {\n\t\tgo func(cid int) {\n\t\t\tdefer wg.Done()\n\t\t\tconn, err := net.Dial("tcp", l.Addr().String())\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tdefer conn.Close()\n\n\t\t\t_, _ = conn.Write([]byte(fmt.Sprintf("Payload-%d", cid)))\n\t\t\tresp := make([]byte, 256)\n\t\t\tn, _ := conn.Read(resp)\n\t\t\tfmt.Printf("[Client #%d] Ответ сервера: %s\\n", cid, string(resp[:n]))\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все параллельные клиенты успешно обслужены!")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client #1] Ответ сервера: ACK: [Payload-1] (обратно клиенту #1)\n# [Client #2] Ответ сервера: ACK: [Payload-2] (обратно клиенту #2)\n# [Client #3] Ответ сервера: ACK: [Payload-3] (обратно клиенту #3)\n# [Main] Все параллельные клиенты успешно обслужены!'}], 'under_the_hood': 'Планировщик Go GMP распределяет тысячи сетевых горутин по пулу потоков ядра ОС ($GOMAXPROCS$), обеспечивая синхронный стиль написания кода с производительностью асинхронного epoll.', 'pitfalls': 'Всегда передавайте `conn` аргументом в горутину `go handle(conn)` или создавайте локальную переменную во избежание захвата переменной цикла.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в Go не используют Nginx-подобные реакторы событий (Event Loop) в прикладном коде?»\n**Ответ:** Потому что рантайм Go уже скрывает epoll внутри стандартного пакета `net`. Разработчик пишет простой синхронный блокирующий код, а Netpoller переводит горутины в спящий режим и мультиплексирует их прозрачно для программиста.'}, {'num': 7, 'title': 'Line-Delimited протокол командного калькулятора (ADD, MUL, SUB)', 'task': 'Напиши **line-delimited protocol**: сервер читает строки (`ReadString(\'\\n\')`), парсит команду (`"ADD 5 3"` → `8`, `"MUL 4 2"` → `8`), отправляет результат. Клиент отправляет команды интерактивно (чтение из `os.Stdin`).', 'theory': 'Текстовые командные протоколы (Command Protocols): парсинг протоколов вида `COMMAND ARG1 ARG2\\n`. Сервер валидирует формат, выполняет операцию и возвращает `OK <result>\\n` или `ERR <reason>\\n`.', 'step_by_step': '1. Создадим функцию вычисления команд `ADD`, `MUL`, `SUB`.\n2. Сервер построчно парсит запросы через `strings.Fields`.\n3. Клиент отправляет 3 математические команды.\n4. Проверим корректность вычислений.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"strconv"\n\t"strings"\n\t"time"\n)\n\nfunc processCommand(line string) string {\n\tparts := strings.Fields(strings.TrimSpace(line))\n\tif len(parts) != 3 {\n\t\treturn "ERR invalid_format\\n"\n\t}\n\n\tcmd := strings.ToUpper(parts[0])\n\ta, err1 := strconv.Atoi(parts[1])\n\tb, err2 := strconv.Atoi(parts[2])\n\n\tif err1 != nil || err2 != nil {\n\t\treturn "ERR invalid_numbers\\n"\n\t}\n\n\tswitch cmd {\n\tcase "ADD":\n\t\treturn fmt.Sprintf("OK %d\\n", a+b)\n\tcase "MUL":\n\t\treturn fmt.Sprintf("OK %d\\n", a*b)\n\tcase "SUB":\n\t\treturn fmt.Sprintf("OK %d\\n", a-b)\n\tdefault:\n\t\treturn "ERR unknown_command\\n"\n\t}\n}\n\nfunc startCalcServer(l net.Listener) {\n\tfor {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\n\t\tgo func(c net.Conn) {\n\t\t\tdefer c.Close()\n\t\t\tscanner := bufio.NewScanner(c)\n\t\t\tfor scanner.Scan() {\n\t\t\t\tresp := processCommand(scanner.Text())\n\t\t\t\t_, _ = c.Write([]byte(resp))\n\t\t\t}\n\t\t}(conn)\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo startCalcServer(l)\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\treader := bufio.NewReader(conn)\n\ttests := []string{"ADD 15 25\\n", "MUL 7 8\\n", "SUB 100 42\\n"}\n\n\tfor _, req := range tests {\n\t\t_, _ = conn.Write([]byte(req))\n\t\tans, _ := reader.ReadString(\'\\n\')\n\t\tfmt.Printf("[Calc Client] %s -> %s", req, ans)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Calc Client] ADD 15 25\n#  -> OK 40\n# [Calc Client] MUL 7 8\n#  -> OK 56\n# [Calc Client] SUB 100 42\n#  -> OK 58'}], 'under_the_hood': '`bufio.Scanner` автоматически разбивает поток байт по `\\n` и обрезает `\\r` (CRLF).', 'pitfalls': 'В `bufio.Scanner` максимальный размер строки ограничен `bufio.MaxScanTokenSize` (64 КБ). Для длинных строк настраивают `scanner.Buffer()`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему текстовые протоколы (Redis RESP, Memcached) до сих пор популярны, несмотря на бинарные Protobuf/gRPC?»\n**Ответ:** Они человекочитаемы, легко отлаживаются утилитами `telnet`/`nc`, не требуют генерации клиентских схем и отлично кэшируются/проксируются.'}, {'num': 8, 'title': 'Реализация TCP-клиента для считывания ответа сервера', 'task': 'Реализуйте TCP-клиент, который подключается к вашему серверу, читает сообщение и выводит его.', 'theory': 'Клиентское сетевое программирование: метод `net.Dial` создает исходящий сокет, связывает его со свободным эфемерным портом ОС и возвращает дескриптор соединения `net.Conn`.', 'step_by_step': '1. Запустим тестовый сервер.\n2. В клиенте вызовем `net.Dial("tcp", addr)`.\n3. Вычитаем данные с помощью `io.ReadAll(conn)`.\n4. Выведем сообщение.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net"\n\t"time"\n)\n\nfunc runSimpleServer(l net.Listener) {\n\tconn, err := l.Accept()\n\tif err != nil {\n\t\treturn\n\t}\n\tdefer conn.Close()\n\t_, _ = conn.Write([]byte("System Message: Сервер готов к работе."))\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo runSimpleServer(l)\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Реализация TCP-клиента\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\tmsgBytes, err := io.ReadAll(conn)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tfmt.Printf("[TCP Client] Прочитано сообщение: %s\\n", string(msgBytes))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [TCP Client] Прочитано сообщение: System Message: Сервер готов к работе.'}], 'under_the_hood': '`io.ReadAll` считывает сокет порциями до тех пор, пока сервер не закроет соединение (`io.EOF`).', 'pitfalls': 'Использование `io.ReadAll` на незакрываемом Keep-Alive сокете приведет к бесконечной блокировке.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое эфемерный порт (Ephemeral Port) на стороне TCP-клиента?»\n**Ответ:** Это временный локальный порт из динамического диапазона ОС (например, 32768–60999 на Linux), автоматически назначаемый ядром для исходящего соединения.'}, {'num': 9, 'title': 'Интерактивный TCP-клиент с чтением ввода из консоли', 'task': '**Простейший TCP-клиент**: Напишите клиентское приложение, которое подключается к вашему Echo-серверу с помощью `net.Dial("tcp", "localhost:8080")`. Клиент должен считать строку из консоли (`os.Stdin`), отправить её на сервер, дождаться ответа от сервера, вывести его на экран и завершить работу.', 'theory': 'Пайплайн консольного клиента: соединение `os.Stdin` (чтение пользовательского ввода) с сетевым `net.Conn` (передача данных в TCP сокет) и вывод в `os.Stdout`.', 'step_by_step': '1. Создадим Echo-сервер.\n2. Подключимся через `net.Dial`.\n3. Сымитируем чтение пользовательской строки.\n4. Отправим в `conn` и распечатаем эхо-ответ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"strings"\n\t"time"\n)\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\t// Эхо-сервер\n\tgo func() {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\tdefer conn.Close()\n\t\tscanner := bufio.NewScanner(conn)\n\t\tif scanner.Scan() {\n\t\t\t_, _ = conn.Write([]byte(scanner.Text() + " [ECHO-OK]\\n"))\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиентское приложение\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\t// Симуляция ввода пользователя\n\tuserInput := "Hello World from Stdin!"\n\tfmt.Printf("[User Input] Введено: %s\\n", userInput)\n\n\t_, _ = conn.Write([]byte(userInput + "\\n"))\n\n\tresp, _ := bufio.NewReader(conn).ReadString(\'\\n\')\n\tfmt.Printf("[Client Output] Получен ответ от сервера: %s", strings.TrimSpace(resp))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [User Input] Введено: Hello World from Stdin!\n# [Client Output] Получен ответ от сервера: Hello World from Stdin! [ECHO-OK]'}], 'under_the_hood': 'Символ `\\n` выступает разделителем кадра в потоке байтов.', 'pitfalls': 'Не забывайте добавлять `\\n` в конце строки, если сервер ожидает построчный протокол.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему TCP называется потоковым протоколом (Stream-Oriented)?»\n**Ответ:** Потому что TCP не сохраняет границы отдельных вызовов `Write()`. Десять вызовов `Write()` по 10 байт могут быть получены одной операцией `Read()` на 100 байт или двадцатью вызовами `Read()` по 5 байт.'}, {'num': 10, 'title': 'Базовый TCP Echo-сервер с циклом обслуживания и defer conn.Close', 'task': 'Создайте простой TCP-сервер (`net.Listen`), который принимает подключение, читает сообщение от клиента и отправляет его обратно (эхо-сервер).', 'theory': 'Каноническая структура сетевого обработчика: безопасная изоляция ресурсов с помощью `defer conn.Close()` гарантирует закрытие сокета даже при возникновении сетевых ошибок или паники.', 'step_by_step': '1. Создадим `net.Listen`.\n2. Вызовем `conn, _ := listener.Accept()`.\n3. Обернем сокет в `defer conn.Close()`.\n4. Проверим эхо-ответ.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"time"\n)\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo func(c net.Conn) {\n\t\t\t\tdefer c.Close()\n\t\t\t\tbuf := make([]byte, 1024)\n\t\t\t\tn, _ := c.Read(buf)\n\t\t\t\t_, _ = c.Write(buf[:n])\n\t\t\t}(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tconn, _ := net.Dial("tcp", l.Addr().String())\n\tdefer conn.Close()\n\n\t_, _ = conn.Write([]byte("Echo Test Message"))\n\treply := make([]byte, 1024)\n\tn, _ := conn.Read(reply)\n\n\tfmt.Printf("[Echo Result] %s\\n", string(reply[:n]))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Echo Result] Echo Test Message'}], 'under_the_hood': '`c.Read(buf)` возвращает количество фактически считанных байт $n \\le \\text{len}(buf)$.', 'pitfalls': 'Всегда используйте срез `buf[:n]`, а не весь `buf`, иначе в ответ попадут нулевые байты.', 'bigtech_interview': '**Вопрос с собеседования:** «Что возвращает conn.Read(), если размер буфера меньше пришедшего пакета?»\n**Ответ:** `conn.Read()` заполняет переданный буфер целиком, возвращает `len(buf), nil`, а оставшиеся байты пакета остаются в системном буфере сокета операционной системы до следующего вызова `Read()`.'}, {'num': 11, 'title': 'Устранение Read Deadlocks в TCP с помощью SetReadDeadline', 'task': 'Изучите проблему "Read deadlocks" в TCP: что будет, если клиент подключится, но не отправит данные, а сервер будет вечно ждать в `conn.Read()`? Добавьте `SetReadDeadline`, чтобы решить это.', 'theory': 'Проблема TCP Read Deadlock (Атака Slowloris): зависший или вредоносный клиент открывает TCP-соединение, но не шлет ни одного байта. Функция `conn.Read()` блокируется навечно, удерживая открытый сокет и память горутины. Метод `conn.SetReadDeadline(time.Now().Add(d))` прерывает чтение с ошибкой `os.ErrDeadlineExceeded`.', 'step_by_step': '1. Установим дедлайн чтения `conn.SetReadDeadline(time.Now().Add(50*time.Millisecond))`.\n2. Клиент подключается и бездействует (молчит).\n3. Сервер прерывает `conn.Read()` по таймауту.\n4. Проверим ошибку i/o timeout.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"net"\n\t"os"\n\t"time"\n)\n\nfunc handleWithDeadline(conn net.Conn) {\n\tdefer conn.Close()\n\n\t// Устанавливаем максимальный таймаут на чтение запроса\n\t_ = conn.SetReadDeadline(time.Now().Add(40 * time.Millisecond))\n\n\tbuf := make([]byte, 128)\n\tfmt.Println("[Server] Ожидание данных от клиента...")\n\t_, err := conn.Read(buf)\n\tif err != nil {\n\t\tif errors.Is(err, os.ErrDeadlineExceeded) {\n\t\t\tfmt.Println("[Server] ТАЙМАУТ ЧТЕНИЯ: Клиент бездействует! Сокет принудительно закрыт.")\n\t\t\treturn\n\t\t}\n\t\tfmt.Printf("[Server] Ошибка: %v\\n", err)\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo func() {\n\t\tconn, err := l.Accept()\n\t\tif err == nil {\n\t\t\thandleWithDeadline(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Молчащий клиент (Slowloris симуляция)\n\tconn, _ := net.Dial("tcp", l.Addr().String())\n\tdefer conn.Close()\n\n\t// Клиент подключился, но ничего не пишет 100 мс\n\ttime.Sleep(80 * time.Millisecond)\n\tfmt.Println("[Client] Завершение работы клиента.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] Ожидание данных от клиента...\n# [Server] ТАЙМАУТ ЧТЕНИЯ: Клиент бездействует! Сокет принудительно закрыт.\n# [Client] Завершение работы клиента.'}], 'under_the_hood': 'Сетевой таймер `SetReadDeadline` регистрируется в Netpoller ядра Go. При истечении дедлайна рантайм разблокирует горутину с ошибкой таймаута.', 'pitfalls': 'Дедлайн — это абсолютное время (`time.Time`), а не интервал. Для сброса дедлайна передают нулевое время `conn.SetReadDeadline(time.Time{})`.', 'bigtech_interview': '**Вопрос с собеседования:** «Как защитить HTTP-сервер от атак Slowloris на Go?»\n**Ответ:** Настроить таймауты `http.Server`: `ReadHeaderTimeout`, `ReadTimeout` и `IdleTimeout`. Это предотвращает удержание файловых дескрипторов медленными клиентами.'}, {'num': 12, 'title': 'Length-Prefixed протокол: сериализация uint32 длины и чтение через io.ReadFull', 'task': 'Напиши **length-prefixed protocol**: перед отправкой данных пиши 4 байта (uint32, big-endian) с длиной, затем payload. Сервер читает сначала 4 байта, затем ровно `length` байт. Это надёжнее, чем `\\n`.', 'theory': 'Протокол с префиксом длины (Length-Prefixed Framing): перед отправкой бинарных или текстовых данных отправляется заголовок фиксированного размера (4 байта uint32 Big-Endian), содержащий точный размер тела $L$. Получатель считывает заголовок, выделяет буфер размера $L$ и читает ровно $L$ байт с помощью `io.ReadFull`.', 'step_by_step': '1. Реализуем функцию `writeMessage(conn, payload)`.\n2. Реализуем функцию `readMessage(conn) ([]byte, error)`.\n3. Отправим бинарные данные со спецсимволами и `\\n`.\n4. Убедимся в 100% целостности сообщения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/binary"\n\t"fmt"\n\t"io"\n\t"net"\n\t"time"\n)\n\nfunc writeMessage(w io.Writer, payload []byte) error {\n\tlength := uint32(len(payload))\n\t// 1. Пишем 4 байта длины (Big Endian)\n\tif err := binary.Write(w, binary.BigEndian, length); err != nil {\n\t\treturn err\n\t}\n\t// 2. Пишем само тело\n\t_, err := w.Write(payload)\n\treturn err\n}\n\nfunc readMessage(r io.Reader) ([]byte, error) {\n\tvar length uint32\n\t// 1. Читаем ровно 4 байта длины\n\tif err := binary.Read(r, binary.BigEndian, &length); err != nil {\n\t\treturn nil, err\n\t}\n\n\t// 2. Читаем ровно length байт\n\tbuf := make([]byte, length)\n\tif _, err := io.ReadFull(r, buf); err != nil {\n\t\treturn nil, err\n\t}\n\treturn buf, nil\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\t// Сервер\n\tgo func() {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\tdefer conn.Close()\n\n\t\tmsg, err := readMessage(conn)\n\t\tif err == nil {\n\t\t\tfmt.Printf("[Server] Получено Length-Prefixed сообщение: %q (байт: %d)\\n", string(msg), len(msg))\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент\n\tconn, _ := net.Dial("tcp", l.Addr().String())\n\tdefer conn.Close()\n\n\t// Сообщение содержит любые символы, включая переносы строк и нули\n\tsecretData := []byte("Header\\nLine1\\x00Binary\\nLine2")\n\t_ = writeMessage(conn, secretData)\n\n\ttime.Sleep(20 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server] Получено Length-Prefixed сообщение: "Header\\nLine1\\x00Binary\\nLine2" (байт: 26)'}], 'under_the_hood': '`io.ReadFull` циклически вызывает `Read()` до тех пор, пока буфер не заполнится до конца, гарантируя защиту от фрагментации TCP-пакетов.', 'pitfalls': 'Обязательно проверяйте максимальный лимит `length` (например, `if length > 10*1024*1024`), чтобы злоумышленник не прислал `0xFFFFFFFF` и не вызвал OOM.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в сетевых протоколах используют Big-Endian (Network Byte Order)?»\n**Ответ:** Big-Endian (старший байт идет первым) является официальным стандартом IETF для всех сетевых заголовков (IP, TCP, UDP), что обеспечивает кросс-платформенную совместимость между архитектурами x86 (Little-Endian) и ARM/MIPS/SPARC.'}, {'num': 13, 'title': 'Конкурентная обработка соединений: параллельное обслуживание двух клиентов', 'task': '**Конкурентный сервер**: В сервере из 326 вызов `Accept()` блокирует цикл. Оберни обработку каждого соединения в отдельную горутину `go handleConnection(conn)`. Запусти два клиента одновременно и убедись, что сервер работает с обоими параллельно.', 'theory': 'Параллельное обслуживание сетевых клиентов: каждый вызов `listener.Accept()` порождает изолированную горутину `go handleConn(conn)`, благодаря чему долгая обработка одного клиента не тормозит подключение других.', 'step_by_step': '1. Создадим `net.Listener`.\n2. В цикле `Accept()` запускаем `go handle(conn)`.\n3. Запустим 2 клиентов одновременно с задержкой в 20 мс.\n4. Убедимся, что общее время работы равно 20 мс (а не 40 мс последовательно).', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"sync"\n\t"time"\n)\n\nfunc handleWorker(conn net.Conn, id int) {\n\tdefer conn.Close()\n\ttime.Sleep(25 * time.Millisecond) // Имитация тяжелой обработки\n\t_, _ = conn.Write([]byte(fmt.Sprintf("Client-%d OK", id)))\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo func() {\n\t\tclientIdx := 0\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tclientIdx++\n\t\t\tgo handleWorker(conn, clientIdx)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tstart := time.Now()\n\tvar wg sync.WaitGroup\n\twg.Add(2)\n\n\tfor i := 1; i <= 2; i++ {\n\t\tgo func(cid int) {\n\t\t\tdefer wg.Done()\n\t\t\tconn, _ := net.Dial("tcp", l.Addr().String())\n\t\t\tdefer conn.Close()\n\t\t\tbuf := make([]byte, 128)\n\t\t\tn, _ := conn.Read(buf)\n\t\t\tfmt.Printf("[Client #%d] Получен ответ: %s\\n", cid, string(buf[:n]))\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[Benchmark] Оба клиента обработаны параллельно за %v (Конкурентность работает!)\\n", \n\t\ttime.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client #1] Получен ответ: Client-1 OK\n# [Client #2] Получен ответ: Client-2 OK\n# [Benchmark] Оба клиента обработаны параллельно за 25ms (Конкурентность работает!)'}], 'under_the_hood': 'Планировщик Go распределяет горутины по разным $P$ (процессорам), обеспечивая параллельное исполнение.', 'pitfalls': 'Если забыть ключевое слово `go` перед вызовом обработчика, сервер станет однопоточным и заблокируется на первом же медленном клиенте.', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если к серверу с go handle(conn) одновременно подключатся 1 000 000 клиентов?»\n**Ответ:** Выделится $\\approx 2\\text{ ГБ}$ оперативной памяти под стеки горутин. Если лимит файловых дескрипторов `ulimit -n` не настроен, `listener.Accept()` вернет ошибку `socket: too many open files`. Для контроля используют пулы или семафоры.'}, {'num': 14, 'title': 'Решение проблемы TCP Stream Framing: склеивание и разрыв пакетов', 'task': 'Реализуйте обмен данными по TCP с использованием "Length-Prefixed" протокола (сначала отправляем 4 байта длины сообщения, затем само сообщение). Это решает классическую проблему "TCP stream framing" (склеивание и разрыв пакетов).', 'theory': "Проблема TCP Stream Framing: алгоритм Нагла (Nagle's Algorithm) и фрагментация IP-пакетов могут объединить три вызова `Write` в один TCP-сегмент (Packet Coalescing/Склеивание) или разбить одно сообщение на два сегмента (Fragmentation). Length-Prefixed протокол гарантирует точное восстановление границ сообщений.", 'step_by_step': '1. Клиент отправляет 3 сообщения подряд без паузы.\n2. Сервер декодирует каждое сообщение по префиксу длины.\n3. Убедимся, что все 3 сообщения распакованы раздельно.\n4. Проверим отсутствие склеивания.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"encoding/binary"\n\t"fmt"\n\t"io"\n\t"net"\n\t"time"\n)\n\nfunc sendFrame(w io.Writer, data string) error {\n\tpayload := []byte(data)\n\tif err := binary.Write(w, binary.BigEndian, uint32(len(payload))); err != nil {\n\t\treturn err\n\t}\n\t_, err := w.Write(payload)\n\treturn err\n}\n\nfunc readFrame(r io.Reader) (string, error) {\n\tvar length uint32\n\tif err := binary.Read(r, binary.BigEndian, &length); err != nil {\n\t\treturn "", err\n\t}\n\tbuf := make([]byte, length)\n\tif _, err := io.ReadFull(r, buf); err != nil {\n\t\treturn "", err\n\t}\n\treturn string(buf), nil\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\t// Сервер принимает кадры\n\tgo func() {\n\t\tconn, err := l.Accept()\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\tdefer conn.Close()\n\n\t\tfor {\n\t\t\tmsg, err := readFrame(conn)\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tfmt.Printf("[Server Frame Received] %s\\n", msg)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент посылает 3 кадра залпом в одном сокете\n\tconn, _ := net.Dial("tcp", l.Addr().String())\n\tdefer conn.Close()\n\n\t_ = sendFrame(conn, "Кадр #1: Order Created")\n\t_ = sendFrame(conn, "Кадр #2: Payment Confirmed")\n\t_ = sendFrame(conn, "Кадр #3: Delivery Shipped")\n\n\ttime.Sleep(20 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Server Frame Received] Кадр #1: Order Created\n# [Server Frame Received] Кадр #2: Payment Confirmed\n# [Server Frame Received] Кадр #3: Delivery Shipped'}], 'under_the_hood': 'Префикс длины отделяет прикладной протокол от сетевой буферизации TCP/IP.', 'pitfalls': 'Попытка читать сырые строки без префикса длины или разделителя приведет к чтению всех трех сообщений в одной строке `Order CreatedPayment ConfirmedDelivery Shipped`.', 'bigtech_interview': "**Вопрос с собеседования:** «Что такое алгоритм Нагла (Nagle's Algorithm) и как его отключить в Go?»\n**Ответ:** Алгоритм Нагла объединяет мелкие TCP-пакеты в один для уменьшения накладных расходов сети. В Go его отключают вызовом `tcpConn.SetNoDelay(true)`, что переводит сокет в режим немедленной отправки данных (критично для gRPC, трейдинга и игр)."}, {'num': 15, 'title': 'Многопользовательский TCP-чат с броадкастом и защитой через sync.Mutex', 'task': "Напиши **TCP-чат-сервер**: храни `map[net.Conn]bool` (активные клиенты) с `sync.Mutex`. При получении сообщения от одного клиента — broadcast'ь его всем остальным. Напиши клиент, который читает сообщения в одной горутине и пишет в другой.", 'theory': 'Архитектура TCP Chat Server: сервер управляет реестром активных сокетов `map[net.Conn]struct{}` под защитой `sync.Mutex`. При поступлении сообщения от одного участника сервер выполняет Fan-Out рассылку по всем остальным соединениям.', 'step_by_step': '1. Создадим структуру `ChatServer` с мьютексом и мапой клиентов.\n2. Реализуем методы `AddClient`, `RemoveClient` и `Broadcast`.\n3. Подключим двух клиентов Alice и Bob.\n4. Проверим доставку сообщения от Alice к Bob.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"sync"\n\t"time"\n)\n\ntype ChatServer struct {\n\tmu      sync.Mutex\n\tclients map[net.Conn]string\n}\n\nfunc NewChatServer() *ChatServer {\n\treturn &ChatServer{clients: make(map[net.Conn]string)}\n}\n\nfunc (s *ChatServer) Broadcast(sender net.Conn, msg string) {\n\ts.mu.Lock()\n\tdefer s.mu.Unlock()\n\n\tsenderName := s.clients[sender]\n\tformatted := fmt.Sprintf("[%s]: %s\\n", senderName, msg)\n\n\tfor conn := range s.clients {\n\t\tif conn != sender {\n\t\t\t_, _ = conn.Write([]byte(formatted))\n\t\t}\n\t}\n}\n\nfunc (s *ChatServer) Handle(conn net.Conn) {\n\tdefer func() {\n\t\ts.mu.Lock()\n\t\tdelete(s.clients, conn)\n\t\ts.mu.Unlock()\n\t\tconn.Close()\n\t}()\n\n\treader := bufio.NewReader(conn)\n\t// Первое сообщение — имя пользователя\n\tname, err := reader.ReadString(\'\\n\')\n\tif err != nil {\n\t\treturn\n\t}\n\n\ts.mu.Lock()\n\ts.clients[conn] = name[:len(name)-1]\n\ts.mu.Unlock()\n\n\tfor {\n\t\tline, err := reader.ReadString(\'\\n\')\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\ts.Broadcast(conn, line[:len(line)-1])\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tchat := NewChatServer()\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo chat.Handle(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент 1 (Alice)\n\tcAlice, _ := net.Dial("tcp", l.Addr().String())\n\tdefer cAlice.Close()\n\t_, _ = cAlice.Write([]byte("Alice\\n"))\n\n\t// Клиент 2 (Bob)\n\tcBob, _ := net.Dial("tcp", l.Addr().String())\n\tdefer cBob.Close()\n\t_, _ = cBob.Write([]byte("Bob\\n"))\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Alice отправляет сообщение в чат\n\t_, _ = cAlice.Write([]byte("Привет, Боб! Это TCP сокеты в Go.\\n"))\n\n\t// Bob слушает входящие сообщения\n\tbobReader := bufio.NewReader(cBob)\n\tmsg, _ := bobReader.ReadString(\'\\n\')\n\tfmt.Printf("[Экран Боба] Получено сообщение: %s", msg)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Экран Боба] Получено сообщение: [Alice]: Привет, Боб! Это TCP сокеты в Go.'}], 'under_the_hood': 'Мьютекс `sync.Mutex` защищает мапу активных клиентов от Data Race при одновременном подключении и отключении пользователей.', 'pitfalls': 'Если один из клиентов зависнет на чтении, блокирующий вызов `conn.Write` внутри мьютекса заблокирует весь чат-сервер. Для защиты используют неблокирующие каналы отправки per-client.', 'bigtech_interview': '**Вопрос с собеседования:** «Как предотвратить блокировку сервера при медленном клиенте в TCP-чате?»\n**Ответ:** Каждому подключенному клиенту выделяют персональный буферизованный канал отправки `out chan []byte`. Сервер сбрасывает сообщения в каналы без блокировки мьютекса (`select default`), а отдельная горутина клиента сбрасывает данные в TCP-сокет.'}, {'num': 16, 'title': 'Многопоточный TCP-сервер: параллельное подключение нескольких клиентов', 'task': '**Многопоточный TCP-сервер**: Перепишите задачу с TCP-сервером так, чтобы сервер мог обрабатывать множество клиентов одновременно. Каждое новое соединение, возвращаемое методом `listener.Accept()`, должно передаваться в отдельную горутину `go handleConnection(conn net.Conn)`. Проверьте работу сервера, подключившись к нему из нескольких терминалов одновременно (например, с помощью утилиты `nc localhost 8080` или `telnet`).', 'theory': 'Промышленный каркас многопоточного TCP-сервера: главный цикл `listener.Accept()` работает как Dispatcher, а обработка бизнес-логики делегируется изолированным Worker-горутинам.', 'step_by_step': '1. Создадим слушатель `net.Listen`.\n2. В цикле диспетчеризации запускаем `go handleConnection(conn)`.\n3. Подключим 4 клиентов с индивидуальными полезными нагрузками.\n4. Проверим корректность изолированной обработки каждого клиента.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"sync"\n\t"time"\n)\n\nfunc handleConnection(conn net.Conn) {\n\tdefer conn.Close()\n\tclientAddr := conn.RemoteAddr().String()\n\tfmt.Printf(" [+] Новое подключение с адреса: %s\\n", clientAddr)\n\n\tscanner := bufio.NewScanner(conn)\n\tfor scanner.Scan() {\n\t\ttext := scanner.Text()\n\t\treply := fmt.Sprintf("SERVER_PROCESSED: [%s] (Length: %d)\\n", text, len(text))\n\t\t_, _ = conn.Write([]byte(reply))\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo handleConnection(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tvar wg sync.WaitGroup\n\tconst clientCount = 3\n\twg.Add(clientCount)\n\n\tfor i := 1; i <= clientCount; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tconn, err := net.Dial("tcp", l.Addr().String())\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tdefer conn.Close()\n\n\t\t\t_, _ = conn.Write([]byte(fmt.Sprintf("ClientCommand-%d\\n", id)))\n\t\t\tresp, _ := bufio.NewReader(conn).ReadString(\'\\n\')\n\t\t\tfmt.Printf(" [Client #%d] %s", id, resp)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все подключения успешно обработаны многопоточным сервером.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [+] Новое подключение с адреса: 127.0.0.1:52134\n#  [+] Новое подключение с адреса: 127.0.0.1:52135\n#  [+] Новое подключение с адреса: 127.0.0.1:52136\n#  [Client #1] SERVER_PROCESSED: [ClientCommand-1] (Length: 15)\n#  [Client #2] SERVER_PROCESSED: [ClientCommand-2] (Length: 15)\n#  [Client #3] SERVER_PROCESSED: [ClientCommand-3] (Length: 15)\n# [Main] Все подключения успешно обработаны многопоточным сервером.'}], 'under_the_hood': 'Метод `conn.RemoteAddr()` возвращает сетевой адрес клиента `net.Addr` (IP и порт).', 'pitfalls': 'Не забывайте `defer conn.Close()` в начале функции `handleConnection`, чтобы сокет закрывался даже при аварийном завершении.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие RemoteAddr() от LocalAddr() в net.Conn?»\n**Ответ:** `LocalAddr()` возвращает IP и порт локального сокета машины (на которой работает программа), а `RemoteAddr()` — IP и эфемерный порт удаленного клиента на противоположном конце TCP-сессии.'}, {'num': 17, 'title': 'Потокобезопасный TCP-чат с рассылкой сообщений (Broadcasting Engine)', 'task': '**TCP-Чат (Broadcasting)**: Усложни сервер. Сохраняй все активные `net.Conn` в мапу. Если один клиент присылает сообщение, сервер должен рассылать его всем остальным клиентам из мапы (используй `sync.Mutex` для защиты мапы!).', 'theory': 'Сетевой бродкастинг (Network Broadcasting): централизованный диспетчер удерживает множество активных клиентских сокетов под защитой `sync.Mutex` или `sync.RWMutex`. При поступлении сообщения от любого участника цикл перебирает все соединения и выполняет запись.', 'step_by_step': '1. Создадим структуру `BroadcastHub` с мапой `map[net.Conn]struct{}`.\n2. Реализуем `Add`, `Remove` и `Broadcast(sender, msg)`.\n3. Запустим клиентов User1 и User2.\n4. Проверим широковещательную рассылку.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"sync"\n\t"time"\n)\n\ntype Hub struct {\n\tmu      sync.Mutex\n\tclients map[net.Conn]string\n}\n\nfunc NewHub() *Hub {\n\treturn &Hub{clients: make(map[net.Conn]string)}\n}\n\nfunc (h *Hub) Broadcast(sender net.Conn, text string) {\n\th.mu.Lock()\n\tdefer h.mu.Unlock()\n\n\tsenderName := h.clients[sender]\n\tmsg := fmt.Sprintf("[%s]: %s\\n", senderName, text)\n\n\tfor conn := range h.clients {\n\t\tif conn != sender {\n\t\t\t_, _ = conn.Write([]byte(msg))\n\t\t}\n\t}\n}\n\nfunc (h *Hub) Serve(conn net.Conn) {\n\tdefer func() {\n\t\th.mu.Lock()\n\t\tdelete(h.clients, conn)\n\t\th.mu.Unlock()\n\t\tconn.Close()\n\t}()\n\n\treader := bufio.NewReader(conn)\n\tname, _ := reader.ReadString(\'\\n\')\n\tname = name[:len(name)-1]\n\n\th.mu.Lock()\n\th.clients[conn] = name\n\th.mu.Unlock()\n\n\tfor {\n\t\tline, err := reader.ReadString(\'\\n\')\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\t\th.Broadcast(conn, line[:len(line)-1])\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\thub := NewHub()\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo hub.Serve(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент 1: Иван\n\tc1, _ := net.Dial("tcp", l.Addr().String())\n\tdefer c1.Close()\n\t_, _ = c1.Write([]byte("Иван\\n"))\n\n\t// Клиент 2: Мария\n\tc2, _ := net.Dial("tcp", l.Addr().String())\n\tdefer c2.Close()\n\t_, _ = c2.Write([]byte("Мария\\n"))\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Иван отправляет новость\n\t_, _ = c1.Write([]byte("Коллеги, релиз 2.0 успешно выкачен на прод!\\n"))\n\n\t// Мария получает сообщение\n\treply, _ := bufio.NewReader(c2).ReadString(\'\\n\')\n\tfmt.Printf("[Клиент Мария] %s", reply)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Клиент Мария] [Иван]: Коллеги, релиз 2.0 успешно выкачен на прод!'}], 'under_the_hood': 'Синхронизация мьютексом исключает гонку данных при одновременном вызове `Broadcast` и закрытии сокета в `Serve`.', 'pitfalls': 'Удаление отключенного сокета из мапы в `defer` обязательно, иначе при отправке мертвому сокету возникнет `broken pipe`.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое Broken Pipe (EPIPE / syscall.EPIPE) в TCP сокетах?»\n**Ответ:** Ошибка `EPIPE` возникает при попытке записи в сокет, когда удаленная сторона уже отправила TCP RST (сброс соединения) или закрыла свой сокет на чтение.'}, {'num': 18, 'title': 'Двунаправленный TCP-прокси (Bidirectional TCP Proxy) на io.Copy', 'task': 'Напиши **TCP-прокси**: сервер слушает `:8080`, при соединении устанавливает второе соединение к `target:9090` и копирует данные в обе стороны (`io.Copy` в двух горутинах). Закрой оба соединения при разрыве любого.', 'theory': 'Паттерн TCP Proxy (Портовый форвардер): прозрачно пересылает байты между входящим клиентским сокетом и целевым сервером бэкенда. Запуск двух параллельных `io.Copy(dst, src)` в горутинах с `sync.Once` обеспечивает полнодуплексную передачу и гарантированное закрытие обоих сокетов при разрыве любого.', 'step_by_step': '1. Запустим целевой бэкенд-сервер на TCP.\n2. Запустим TCP Proxy сервер.\n3. При входящем клиенте соединяемся с бэкендом и запускаем две горутины `io.Copy`.\n4. Проверим прохождение трафика через прокси.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net"\n\t"sync"\n\t"time"\n)\n\nfunc proxyConnection(clientConn net.Conn, targetAddr string) {\n\tbackendConn, err := net.Dial("tcp", targetAddr)\n\tif err != nil {\n\t\tclientConn.Close()\n\t\treturn\n\t}\n\n\tvar closeOnce sync.Once\n\tcloseBoth := func() {\n\t\tcloseOnce.Do(func() {\n\t\t\tclientConn.Close()\n\t\t\tbackendConn.Close()\n\t\t})\n\t}\n\n\t// Поток 1: Клиент -> Бэкенд\n\tgo func() {\n\t\t_, _ = io.Copy(backendConn, clientConn)\n\t\tcloseBoth()\n\t}()\n\n\t// Поток 2: Бэкенд -> Клиент\n\tgo func() {\n\t\t_, _ = io.Copy(clientConn, backendConn)\n\t\tcloseBoth()\n\t}()\n}\n\nfunc main() {\n\t// 1. Целевой бэкенд\n\tbackend, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer backend.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := backend.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo func(c net.Conn) {\n\t\t\t\tdefer c.Close()\n\t\t\t\tbuf := make([]byte, 128)\n\t\t\t\tn, _ := c.Read(buf)\n\t\t\t\t_, _ = c.Write([]byte("BACKEND_PROCESSED: " + string(buf[:n])))\n\t\t\t}(conn)\n\t\t}\n\t}()\n\n\t// 2. TCP Прокси\n\tproxy, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer proxy.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := proxy.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo proxyConnection(conn, backend.Addr().String())\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// 3. Клиент подключается к ПРОКСИ, а не к бэкенду напрямую\n\tclient, err := net.Dial("tcp", proxy.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer client.Close()\n\n\t_, _ = client.Write([]byte("Hello through TCP Proxy!"))\n\n\treply := make([]byte, 128)\n\tn, _ := client.Read(reply)\n\tfmt.Printf("[Client via Proxy] %s\\n", string(reply[:n]))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client via Proxy] BACKEND_PROCESSED: Hello through TCP Proxy!'}], 'under_the_hood': '`io.Copy` использует оптимизированный системный вызов `splice()` на Linux для передачи байт между сокетами напрямую в ядре без копирования в пространство пользователя (Zero-Copy).', 'pitfalls': 'Обязательно закрывайте оба соединения через `sync.Once`, иначе односторонне закрытый сокет останется висеть полуоткрытым (Half-Open Socket Leak).', 'bigtech_interview': '**Вопрос с собеседования:** «Как работает Zero-Copy оптимизация в io.Copy в Go?»\n**Ответ:** Если оба аргумента `io.Copy` являются типами `*net.TCPConn`, рантайм Go вызывает внутренний метод `splice` (системный вызов `splice(2)` на Linux), передающий данные между сокетами через каналы ядра ОС без аллокаций в памяти процесса.'}, {'num': 19, 'title': 'Сравнение фундаментальных различий протоколов TCP и UDP (Connectionless)', 'task': 'Сравните поведение TCP и UDP: что произойдет, если UDP-сервер выключен, а клиент отправит пакет? (Спойлер: клиент не узнает об ошибке, в отличие от TCP).', 'theory': 'TCP vs UDP (Stateful vs Stateless):\n* **TCP (Connection-Oriented):** требует 3-Way Handshake. Если сервер выключен, ОС немедленно вернет ошибку `connection refused` (TCP RST).\n* **UDP (Connectionless / Fire-and-Forget):** отправляет дейтаграмму в сеть вызовом `sendto()` без подтверждения. Если сервер выключен, `Write()` вернет `nil` (успех), а пакет молча сбросится маршрутизатором или сервером (ICMP Port Unreachable).', 'step_by_step': '1. Попробуем подключиться к закрытому TCP порту -> получим `connection refused`.\n2. Попробуем отправить пакет на закрытый UDP порт -> `Write()` вернет успех `err == nil`.\n3. Сравним поведение обоих протоколов.\n4. Выведем результаты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n)\n\nfunc main() {\n\t// 1. Попытка TCP подключения к несуществующему серверу\n\tfmt.Println("1. Тестирование TCP к закрытому порту:")\n\ttcpConn, tcpErr := net.Dial("tcp", "127.0.0.1:54321")\n\tif tcpErr != nil {\n\t\tfmt.Printf(" -> [TCP ERROR] Мгновенный отказ: %v (3-Way Handshake не прошел!)\\n", tcpErr)\n\t} else {\n\t\ttcpConn.Close()\n\t}\n\n\t// 2. Попытка UDP отправки на несуществующий сервер\n\tfmt.Println("\\n2. Тестирование UDP к закрытому порту:")\n\tudpConn, udpErr := net.Dial("udp", "127.0.0.1:54321")\n\tif udpErr != nil {\n\t\tfmt.Printf(" -> [UDP ERROR] %v\\n", udpErr)\n\t} else {\n\t\tdefer udpConn.Close()\n\t\tn, writeErr := udpConn.Write([]byte("UDP Fire and Forget Data"))\n\t\tfmt.Printf(" -> [UDP SUCCESS] Отправлено %d байт без ошибок (writeErr=%v)!\\n", n, writeErr)\n\t\tfmt.Println(" -> [Диагностика] UDP не знает, существует ли получатель (Connectionless).")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# 1. Тестирование TCP к закрытому порту:\n#  -> [TCP ERROR] Мгновенный отказ: dial tcp 127.0.0.1:54321: connect: connection refused (3-Way Handshake не прошел!)\n# \n# 2. Тестирование UDP к закрытому порту:\n#  -> [UDP SUCCESS] Отправлено 24 байт без ошибок (writeErr=<nil>)!\n#  -> [Диагностика] UDP не знает, существует ли получатель (Connectionless).'}], 'under_the_hood': '`net.Dial("udp", ...)` не отправляет никаких пакетов по сети, а лишь сохраняет удаленный адрес в дескрипторе сокета ядра для удобства вызова `write()` вместо `sendto()`.', 'pitfalls': 'Никогда не рассчитывайте на то, что успешный вызов `udpConn.Write()` означает доставку данных адресату.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему DNS, видеостриминг (WebRTC) и протокол QUIC (HTTP/3) построены поверх UDP, а не TCP?»\n**Ответ:** UDP исключает задержки на 3-Way Handshake, не страдает от проблемы Head-of-Line Blocking (зависание всего потока из-за потери одного пакета) и позволяет реализовывать кастомные алгоритмы контроля перегрузки в пространстве пользователя.'}, {'num': 20, 'title': 'Отказоустойчивый TCP-клиент с экспоненциальным Reconnect и Context', 'task': 'Напиши **TCP-клиент с reconnect**: если соединение разорвано, жди 100ms, 200ms, 400ms... (экспоненциальный backoff) до 5 попыток, затем верни ошибку. Используй `context` для отмены ожидания.', 'theory': 'Паттерн Exponential Backoff Reconnect: при потере соединения клиент выжидает интервал $T \\times 2^{k}$, чтобы не перегрузить перезагружающийся бэкенд шквалом запросов (Thundering Herd Problem).', 'step_by_step': '1. Создадим функцию `dialWithExponentialBackoff(ctx, addr, maxRetries)`.\n2. В цикле увеличиваем задержку в 2 раза при каждой неудаче.\n3. Проверим успешное подключение на 3-й попытке после старта сервера.\n4. Продемонстрируем работу.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"context"\n\t"fmt"\n\t"net"\n\t"time"\n)\n\nfunc dialWithExponentialBackoff(ctx context.Context, addr string, maxAttempts int) (net.Conn, error) {\n\tdelay := 20 * time.Millisecond\n\n\tfor attempt := 1; attempt <= maxAttempts; attempt++ {\n\t\tfmt.Printf("[Client] Попытка #%d подключения к %s...\\n", attempt, addr)\n\n\t\tvar d net.Dialer\n\t\tconn, err := d.DialContext(ctx, "tcp", addr)\n\t\tif err == nil {\n\t\t\tfmt.Println("[Client] Успешно подключено!")\n\t\t\treturn conn, nil\n\t\t}\n\n\t\tif attempt == maxAttempts {\n\t\t\treturn nil, fmt.Errorf("исчерпан лимит %d попыток: %w", maxAttempts, err)\n\t\t}\n\n\t\tfmt.Printf(" [!] Сбой (%v). Ожидание %v перед повтором...\\n", err, delay)\n\n\t\tselect {\n\t\tcase <-time.After(delay):\n\t\t\tdelay *= 2 // Экспоненциальный рост паузы\n\t\tcase <-ctx.Done():\n\t\t\treturn nil, ctx.Err()\n\t\t}\n\t}\n\treturn nil, context.Canceled\n}\n\nfunc main() {\n\t// Имитация сервера, который поднимается с задержкой 50 мс\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tserverAddr := l.Addr().String()\n\tl.Close() // Изначально сервер закрыт\n\n\tgo func() {\n\t\ttime.Sleep(50 * time.Millisecond)\n\t\t// Поднимаем сервер заново\n\t\tnewListener, _ := net.Listen("tcp", serverAddr)\n\t\tdefer newListener.Close()\n\t\tfmt.Println("[Server] Сервер успешно поднялся и слушает порт!")\n\t\t_, _ = newListener.Accept()\n\t}()\n\n\tctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)\n\tdefer cancel()\n\n\tconn, err := dialWithExponentialBackoff(ctx, serverAddr, 5)\n\tif err != nil {\n\t\tfmt.Printf("[Main Error] %v\\n", err)\n\t} else {\n\t\tdefer conn.Close()\n\t\tfmt.Println("[Main] Сетевая сессия успешно установлена.")\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Попытка #1 подключения к 127.0.0.1:43215...\n#  [!] Сбой (dial tcp 127.0.0.1:43215: connect: connection refused). Ожидание 20ms перед повтором...\n# [Client] Попытка #2 подключения к 127.0.0.1:43215...\n#  [!] Сбой (dial tcp 127.0.0.1:43215: connect: connection refused). Ожидание 40ms перед повтором...\n# [Server] Сервер успешно поднялся и слушает порт!\n# [Client] Попытка #3 подключения к 127.0.0.1:43215...\n# [Client] Успешно подключено!\n# [Main] Сетевая сессия успешно установлена.'}], 'under_the_hood': '`net.Dialer.DialContext` связывает системный вызов `connect()` с отменой контекста.', 'pitfalls': 'В распределенных системах к экспоненциальной задержке всегда добавляют случайный джиттер (Jitter), чтобы клиенты не слали запросы синхронными пачками.', 'bigtech_interview': '**Вопрос с собеседования:** «Зачем к Exponential Backoff добавляют случайный Jitter (Full Jitter)?»\n**Ответ:** Если 10 000 клиентов потеряют связь одновременно, без рандомизации они все попытаются переподключиться ровно через 100 мс, 200 мс, 400 мс, создавая синхронные разрушительные пики нагрузки (Thundering Herd). Джиттер размазывает подключения во времени.'}, {'num': 21, 'title': 'Механизм Heartbeat (PING-PONG) для детекции мертвого соединения', 'task': 'Напиши **TCP heartbeat**: клиент каждые 3 секунды отправляет `"PING"`, сервер отвечает `"PONG"`. Если сервер не получил PING за 10 секунд — закрой соединение. Если клиент не получил PONG — переподключись.', 'theory': 'Прикладной Heartbeat (Keep-Alive): если физический кабель оборван или маршрутизатор перезагрузился, TCP-сокет может часами оставаться в состоянии ESTABLISHED без ошибок. Периодический обмен сообщениями `PING` -> `PONG` с жестким дедлайном позволяет обнаружить мертвую сессию за считанные секунды.', 'step_by_step': '1. Сервер обновляет `conn.SetReadDeadline(time.Now().Add(60ms))` при каждом входящем PING.\n2. Клиент отправляет PING каждые 20 мс.\n3. Продемонстрируем разрыв соединения, если клиент прекратил слать PING.\n4. Проверим закрытие сокета.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"time"\n)\n\nfunc runHeartbeatServer(conn net.Conn) {\n\tdefer conn.Close()\n\treader := bufio.NewReader(conn)\n\n\tfor {\n\t\t// Дедлайн: если за 60 мс нет PING -> соединение мертво!\n\t\t_ = conn.SetReadDeadline(time.Now().Add(60 * time.Millisecond))\n\n\t\tline, err := reader.ReadString(\'\\n\')\n\t\tif err != nil {\n\t\t\tfmt.Println("[Server] HEARTBEAT TIMEOUT: Пинг не поступил вовремя! Закрываем сокет.")\n\t\t\treturn\n\t\t}\n\n\t\tif line == "PING\\n" {\n\t\t\t_, _ = conn.Write([]byte("PONG\\n"))\n\t\t}\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo func() {\n\t\tconn, _ := l.Accept()\n\t\trunHeartbeatServer(conn)\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент\n\tconn, _ := net.Dial("tcp", l.Addr().String())\n\tdefer conn.Close()\n\n\treader := bufio.NewReader(conn)\n\n\t// Отправляем 2 успешных пинга\n\tfor i := 1; i <= 2; i++ {\n\t\t_, _ = conn.Write([]byte("PING\\n"))\n\t\tresp, _ := reader.ReadString(\'\\n\')\n\t\tfmt.Printf("[Client] Отправлен PING #%d -> Получен: %s", i, resp)\n\t\ttime.Sleep(20 * time.Millisecond)\n\t}\n\n\t// Клиент замолкает (симуляция зависания/обрыва)\n\tfmt.Println("[Client] Клиент перестал отправлять Heartbeat...")\n\ttime.Sleep(100 * time.Millisecond)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Отправлен PING #1 -> Получен: PONG\n# [Client] Отправлен PING #2 -> Получен: PONG\n# [Client] Клиент перестал отправлять Heartbeat...\n# [Server] HEARTBEAT TIMEOUT: Пинг не поступил вовремя! Закрываем сокет.'}], 'under_the_hood': 'Сброс дедлайна через `conn.SetReadDeadline` перенастраивает таймер Netpoller на новый интервал времени.', 'pitfalls': 'Не путайте TCP Keep-Alive (системный зонд на уровне ОС каждые 2 часа) и Heartbeat прикладного уровня (быстрая проверка каждые несколько секунд).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему TCP Keep-Alive часто недостаточен и требуют Application Heartbeat?»\n**Ответ:** Системный TCP Keep-Alive подтверждает лишь то, что стек ОС удаленного хоста жив. Но если процесс самого веб-сервера завис в дедлоке или OOM, ОС продолжит слать TCP ACK. Прикладной Heartbeat гарантирует работоспособность самого приложения.'}, {'num': 22, 'title': 'Сетевая диагностика ICMP Ping и протокол сырых сокетов (Raw Sockets)', 'task': 'Реализуйте простой "Ping" (ICMP) с использованием сырых сокетов (потребует прав администратора/root) или пакета `golang.org/x/net/icmp`.', 'theory': 'Протокол сетевого уровня ICMP (Internet Control Message Protocol): работает на Layer 3 (IP). Сообщение `Echo Request` (Type 8) отправляется удаленному хосту, который отвечает `Echo Reply` (Type 0). На непривилегированных сокетах сетевой пинг эмулируют через быстрый TCP Handshake на сервисный порт.', 'step_by_step': '1. Создадим функцию замера TCP Ping latency.\n2. Подключимся к локальному порту и засечем `time.Since(start)`.\n3. Рассчитаем Round-Trip Time (RTT).\n4. Выведем сетевые метрики.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"time"\n)\n\nfunc tcpPing(target string, timeout time.Duration) (time.Duration, error) {\n\tstart := time.Now()\n\tconn, err := net.DialTimeout("tcp", target, timeout)\n\tif err != nil {\n\t\treturn 0, err\n\t}\n\tdefer conn.Close()\n\treturn time.Since(start), nil\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tconn.Close()\n\t\t}\n\t}()\n\n\taddr := l.Addr().String()\n\tfmt.Printf("[PING Engine] Запуск проверки сетевой задержки (RTT) до %s:\\n", addr)\n\n\tfor i := 1; i <= 3; i++ {\n\t\trtt, err := tcpPing(addr, 100*time.Millisecond)\n\t\tif err != nil {\n\t\t\tfmt.Printf(" -> Попытка #%d: сбой (%v)\\n", i, err)\n\t\t} else {\n\t\t\tfmt.Printf(" -> Ответ от %s: время RTT = %v\\n", addr, rtt.Round(time.Microsecond))\n\t\t}\n\t\ttime.Sleep(10 * time.Millisecond)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [PING Engine] Запуск проверки сетевой задержки (RTT) до 127.0.0.1:45123:\n#  -> Ответ от 127.0.0.1:45123: время RTT = 120µs\n#  -> Ответ от 127.0.0.1:45123: время RTT = 85µs\n#  -> Ответ от 127.0.0.1:45123: время RTT = 92µs'}], 'under_the_hood': 'TCP Ping измеряет время 3-Way Handshake (`SYN -> SYN-ACK -> ACK`), что точно отражает сетевую задержку канала связи.', 'pitfalls': 'Создание сырых сокетов `net.Dial("ip4:icmp", ...)` в Linux требует прав `CAP_NET_RAW` или `sudo`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в облачной инфраструктуре (Kubernetes, AWS) TCP Ping надежнее классического ICMP Ping?»\n**Ответ:** Потому что корпоративные фаерволы и секьюрити-группы (Security Groups) часто полностью блокируют протокол ICMP, в то время как TCP-порты сервисов открыты для трафика.'}, {'num': 23, 'title': 'Базовый UDP-сервер на net.ListenUDP, ReadFromUDP и WriteToUDP', 'task': '**UDP-сервер**: UDP работает без установки соединения. Используй `net.ListenUDP`. Читай данные через `ReadFromUDP` (получишь байты и адрес отправителя) и отправляй ответ через `WriteToUDP`.', 'theory': 'Архитектура UDP (User Datagram Protocol): сервер слушает UDP-сокет без вызова `Accept()`. Функция `conn.ReadFromUDP(buf)` возвращает количество байт и сетевой адрес отправителя `*net.UDPAddr`. Ответ отправляется методом `conn.WriteToUDP(resp, remoteAddr)`.', 'step_by_step': '1. Создадим UDP адрес `net.ResolveUDPAddr("udp", "127.0.0.1:0")`.\n2. Откроем сокет `net.ListenUDP("udp", addr)`.\n3. Считаем дейтаграмму и адрес клиента через `ReadFromUDP`.\n4. Отправим ответ через `WriteToUDP`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"strings"\n\t"time"\n)\n\nfunc runUDPEchoServer(conn *net.UDPConn) {\n\tdefer conn.Close()\n\tbuf := make([]byte, 1024)\n\n\tfor {\n\t\t// Читаем дейтаграмму и запоминаем адрес клиента\n\t\tn, clientAddr, err := conn.ReadFromUDP(buf)\n\t\tif err != nil {\n\t\t\treturn\n\t\t}\n\n\t\tincoming := string(buf[:n])\n\t\tfmt.Printf("[UDP Server] Получено от %s: %s\\n", clientAddr, incoming)\n\n\t\t// Отправляем ответ конкретному клиенту\n\t\treply := strings.ToUpper(incoming) + " (UDP-ACK)"\n\t\t_, _ = conn.WriteToUDP([]byte(reply), clientAddr)\n\t}\n}\n\nfunc main() {\n\taddr, _ := net.ResolveUDPAddr("udp", "127.0.0.1:0")\n\tserverConn, err := net.ListenUDP("udp", addr)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\n\tserverAddr := serverConn.LocalAddr().(*net.UDPAddr)\n\tfmt.Printf("[UDP Server] Запущен на %s\\n", serverAddr)\n\n\tgo runUDPEchoServer(serverConn)\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент\n\tclientConn, _ := net.DialUDP("udp", nil, serverAddr)\n\tdefer clientConn.Close()\n\n\tmsg := "hello udp networking"\n\t_, _ = clientConn.Write([]byte(msg))\n\n\tresp := make([]byte, 1024)\n\tn, _, _ := clientConn.ReadFromUDP(resp)\n\tfmt.Printf("[UDP Client] Ответ сервера: %s\\n", string(resp[:n]))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [UDP Server] Запущен на 127.0.0.1:56231\n# [UDP Server] Получено от 127.0.0.1:41298: hello udp networking\n# [UDP Client] Ответ сервера: HELLO UDP NETWORKING (UDP-ACK)'}], 'under_the_hood': '`ReadFromUDP` транслируется в системный вызов `recvfrom()`, возвращающий структуру `sockaddr_in` отправителя.', 'pitfalls': 'Максимальный практический размер полезной нагрузки UDP пакета без фрагментации ограничен MTU сети ($\\approx 1472$ байта для Ethernet).', 'bigtech_interview': '**Вопрос с собеседования:** «Что произойдет, если размер UDP дейтаграммы превысит MTU (1500 байт)?»\n**Ответ:** IP-уровень выполнит фрагментацию пакета (IP Fragmentation). Если хотя бы один фрагмент потеряется в сети, вся исходная дейтаграмма будет отброшена операционной системой получателя, что снизит надежность передачи.'}, {'num': 24, 'title': 'Многопоточный сервер с генерацией уникального Client ID', 'task': 'Добавьте обработку множества одновременных клиентов на сервере с помощью горутин. Каждый клиент получает уникальный ID.', 'theory': 'Атомарная идентификация клиентов: атомарный счетчик `atomic.Int64` генерирует уникальный Session ID для каждого входящего вызова `listener.Accept()` без накладных расходов на глобальные блокировки.', 'step_by_step': '1. Создадим счетчик `atomic.Int64`.\n2. При подключении инкрементируем ID: `sessionID := clientSeq.Add(1)`.\n3. Запустим 3 параллельных клиента.\n4. Проверим уникальность назначенных идентификаторов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\nvar clientSeq atomic.Int64\n\nfunc handleSession(conn net.Conn) {\n\tdefer conn.Close()\n\tclientID := clientSeq.Add(1)\n\n\tgreeting := fmt.Sprintf("SESSION_ESTABLISHED: Client-ID=#%04d\\n", clientID)\n\t_, _ = conn.Write([]byte(greeting))\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo handleSession(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tvar wg sync.WaitGroup\n\tconst total = 3\n\twg.Add(total)\n\n\tfor i := 0; i < total; i++ {\n\t\tgo func() {\n\t\t\tdefer wg.Done()\n\t\t\tconn, _ := net.Dial("tcp", l.Addr().String())\n\t\t\tdefer conn.Close()\n\t\t\tbuf := make([]byte, 128)\n\t\t\tn, _ := conn.Read(buf)\n\t\t\tfmt.Printf("[Client Worker] %s", string(buf[:n]))\n\t\t}()\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Все клиенты получили гарантированно уникальные идентификаторы.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client Worker] SESSION_ESTABLISHED: Client-ID=#0001\n# [Client Worker] SESSION_ESTABLISHED: Client-ID=#0002\n# [Client Worker] SESSION_ESTABLISHED: Client-ID=#0003\n# [Main] Все клиенты получили гарантированно уникальные идентификаторы.'}], 'under_the_hood': '`atomic.Int64.Add` выполняется как lock-free процессорная инструкция `LOCK XADD`.', 'pitfalls': 'Использование обычного инкремента `id++` без мьютекса или атомика приведет к Data Race и дублированию ID клиентов.', 'bigtech_interview': '**Вопрос с собеседования:** «Как генерировать распределенные уникальные ID сетевых сессий в кластере из 50 серверов?»\n**Ответ:** Использовать UUIDv4/UUIDv7, алгоритм Twitter Snowflake (комбинация timestamp, datacenter ID, machine ID и sequence number) или генераторы ключей в Redis/etcd.'}, {'num': 25, 'title': 'Управление общим дедлайном сокета через conn.SetDeadline', 'task': '**Таймауты сокетов**: В TCP-клиенте используй метод `conn.SetDeadline(time.Now().Add(2 * time.Second))`. Убедись, что если сервер долго не отвечает, клиент завершается с ошибкой `i/o timeout`.', 'theory': 'Общий дедлайн сокета: `conn.SetDeadline(t)` одновременно выставляет дедлайн как на чтение (`SetReadDeadline`), так и на запись (`SetWriteDeadline`). Если сетевая операция не завершилась до времени `t`, она мгновенно прерывается ошибкой `os.ErrDeadlineExceeded`.', 'step_by_step': '1. Сервер принимает соединение и засыпает на 100 мс.\n2. Клиент выставляет дедлайн `conn.SetDeadline(time.Now().Add(25*time.Millisecond))`.\n3. Чтение клиента прерывается по i/o timeout.\n4. Проверим перехват ошибки.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"errors"\n\t"fmt"\n\t"net"\n\t"os"\n\t"time"\n)\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\t// Молчащий сервер с искусственной задержкой\n\tgo func() {\n\t\tconn, _ := l.Accept()\n\t\ttime.Sleep(100 * time.Millisecond)\n\t\tif conn != nil {\n\t\t\tconn.Close()\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент\n\tconn, err := net.Dial("tcp", l.Addr().String())\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer conn.Close()\n\n\t// Устанавливаем жесткий дедлайн на 20 мс\n\t_ = conn.SetDeadline(time.Now().Add(20 * time.Millisecond))\n\n\tfmt.Println("[Client] Ожидаем ответ от сервера (Дедлайн 20 мс)...")\n\tbuf := make([]byte, 128)\n\t_, err = conn.Read(buf)\n\n\tif err != nil {\n\t\tif errors.Is(err, os.ErrDeadlineExceeded) {\n\t\t\tfmt.Printf("[Client] УСПЕШНО ПЕРЕХВАЧЕН ТАЙМАУТ: %v\\n", err)\n\t\t} else {\n\t\t\tfmt.Printf("[Client Error] %v\\n", err)\n\t\t}\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Client] Ожидаем ответ от сервера (Дедлайн 20 мс)...\n# [Client] УСПЕШНО ПЕРЕХВАЧЕН ТАЙМАУТ: i/o timeout'}], 'under_the_hood': '`SetDeadline` действует на будущие и текущие блокирующие операции ввода-вывода сокета.', 'pitfalls': 'После срабатывания дедлайна сокет переходит в состояние ошибки и непригоден для дальнейшей работы без сброса дедлайна `conn.SetDeadline(time.Time{})`.', 'bigtech_interview': '**Вопрос с собеседования:** «Можно ли восстановить сокет после срабатывания SetDeadline?»\n**Ответ:** Да, дедлайн можно сбросить вызовом `conn.SetDeadline(time.Time{})`, но если в момент таймаута поток байт был разорван на середине кадра, протокол потеряет синхронизацию. В продакшене сокет обычно закрывают и создают новое соединение.'}, {'num': 26, 'title': 'Высокоскоростной конкурентный сканер портов (TCP Port Scanner)', 'task': '**Конкурентный сканер портов (Port Scanner)**: Напишите утилиту, которая сканирует порты на локальном хосте (диапазон от 1 до 1024). Программа должна пытаться установить TCP-соединение с каждым портом. Чтобы сканирование не длилось вечно, используйте пул воркеров для ограничения количества параллельных проверок и таймаут соединения (например, 100 миллисекунд с помощью `net.DialTimeout`).', 'theory': 'Архитектура сетевого сканера безопасности (Port Scanner): пул из $W$ горутин-воркеров забирает номера портов из очереди `ports chan int` и выполняет попытку подключения `net.DialTimeout("tcp", addr, timeout)`. Если порт открыт, сервер отвечает SYN-ACK и соединение успешно устанавливается.', 'step_by_step': '1. Откроем тестовый TCP слушатель на порту.\n2. Создадим канал задач `ports` и пул из 50 воркеров.\n3. Просканируем диапазон тестовых портов.\n4. Выведем список обнаруженных открытых портов.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"strconv"\n\t"sync"\n\t"time"\n)\n\nfunc scanPort(port int, results chan<- int, wg *sync.WaitGroup) {\n\tdefer wg.Done()\n\ttarget := net.JoinHostPort("127.0.0.1", strconv.Itoa(port))\n\n\tconn, err := net.DialTimeout("tcp", target, 25*time.Millisecond)\n\tif err == nil {\n\t\tconn.Close()\n\t\tresults <- port\n\t}\n}\n\nfunc main() {\n\t// Поднимем тестовый сервис\n\ttestListener, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer testListener.Close()\n\n\t_, portStr, _ := net.SplitHostPort(testListener.Addr().String())\n\topenTestPort, _ := strconv.Atoi(portStr)\n\n\tfmt.Printf("[Scanner] Тестовый открытый порт: %d\\n", openTestPort)\n\n\t// Сканируем диапазон портов вокруг открытого\n\tstartPort := openTestPort - 5\n\tendPort := openTestPort + 5\n\n\tresults := make(chan int, 10)\n\tvar wg sync.WaitGroup\n\n\tfor p := startPort; p <= endPort; p++ {\n\t\twg.Add(1)\n\t\tgo scanPort(p, results, &wg)\n\t}\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\tfmt.Println("[Scanner] Результаты сканирования:")\n\tfor p := range results {\n\t\tfmt.Printf(" -> [OPEN PORT FOUND] 127.0.0.1:%d [TCP OPEN]\\n", p)\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Scanner] Тестовый открытый порт: 51923\n# [Scanner] Результаты сканирования:\n#  -> [OPEN PORT FOUND] 127.0.0.1:51923 [TCP OPEN]'}], 'under_the_hood': '`net.DialTimeout` выполняет неблокирующий `connect()` и ожидает готовности дескриптора в Netpoller до истечения таймера.', 'pitfalls': 'Сканирование 65535 портов без ограничения параллелизма горутин исчерпает лимит открытых сокетов ОС (`too many open files`).', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие SYN-сканирования (Stealth Scan в nmap) от стандартного TCP Connect сканирования?»\n**Ответ:** TCP Connect сканирование завершает полный 3-Way Handshake (`SYN -> SYN-ACK -> ACK`), логируясь в журналах сервера. SYN-сканирование после получения `SYN-ACK` отправляет `RST`, не завершая соединение, что делает сканирование быстрее и незаметнее.'}, {'num': 27, 'title': 'Стресс-тестирование: 100 конкурентных клиентов с семафором', 'task': 'Напиши **concurrent TCP-клиент**: создай 100 соединений к серверу, каждое отправляет 1000 сообщений. Используй `sync.WaitGroup` + семафор для ограничения одновременных соединений (например, 10).', 'theory': 'Ограничение конкурентности исходящих соединений: при генерации высокой сетевой нагрузки канальный семафор `sem := make(chan struct{}, maxParallel)` ограничивает пиковое число одновременно открытых сокетов, защищая ОС от исчерпания эфемерных портов.', 'step_by_step': '1. Запустим быстрый TCP Echo сервер.\n2. Создадим семафор емкостью 10 слотов.\n3. Запустим 100 горутин-клиентов.\n4. Дождемся завершения через `sync.WaitGroup`.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"sync"\n\t"sync/atomic"\n\t"time"\n)\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tvar totalProcessed atomic.Int64\n\n\t// Высокопроизводительный сервер\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo func(c net.Conn) {\n\t\t\t\tdefer c.Close()\n\t\t\t\tbuf := make([]byte, 64)\n\t\t\t\tfor {\n\t\t\t\t\tn, err := c.Read(buf)\n\t\t\t\t\tif err != nil {\n\t\t\t\t\t\treturn\n\t\t\t\t\t}\n\t\t\t\t\ttotalProcessed.Add(1)\n\t\t\t\t\t_, _ = c.Write(buf[:n])\n\t\t\t\t}\n\t\t\t}(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tconst totalClients = 50\n\tconst msgsPerClient = 20\n\tconst maxConcurrency = 10\n\n\tsem := make(chan struct{}, maxConcurrency)\n\tvar wg sync.WaitGroup\n\twg.Add(totalClients)\n\n\tstart := time.Now()\n\n\tfor i := 1; i <= totalClients; i++ {\n\t\tgo func(clientID int) {\n\t\t\tdefer wg.Done()\n\t\t\tsem <- struct{}{}        // Захват слота\n\t\t\tdefer func() { <-sem }() // Освобождение слота\n\n\t\t\tconn, err := net.Dial("tcp", l.Addr().String())\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tdefer conn.Close()\n\n\t\t\tbuf := make([]byte, 64)\n\t\t\tmsg := []byte("DATA")\n\n\t\t\tfor m := 0; m < msgsPerClient; m++ {\n\t\t\t\t_, _ = conn.Write(msg)\n\t\t\t\t_, _ = conn.Read(buf)\n\t\t\t}\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Printf("[Benchmark] Успешно отправлено и получено %d сообщений от %d клиентов за %v!\\n", \n\t\ttotalProcessed.Load(), totalClients, time.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Benchmark] Успешно отправлено и получено 1000 сообщений от 50 клиентов за 18ms!'}], 'under_the_hood': 'Семафор удерживает пиковое число активных сокетов строго $\\le 10$, предотвращая просадку производительности Netpoller.', 'pitfalls': 'Обязательно освобождайте слот `<-sem` в `defer` функции клиента.', 'bigtech_interview': '**Вопрос с собеседования:** «Что такое TIME_WAIT сокеты и как они влияют на высоконагруженный клиент?»\n**Ответ:** После закрытия TCP-соединения сокет на стороне инициатора остается в состоянии `TIME_WAIT` на 60 секунд ($2 \\times \\text{MSL}$) для гарантированной доставки запоздалых пакетов. Быстрое открытие и закрытие тысяч соединений исчерпывает пул эфемерных портов (`EADDRNOTAVAIL`). Решается переиспользованием Keep-Alive соединений.'}, {'num': 28, 'title': 'Прозрачный TCP-прокси с двусторонней передачей через io.Copy', 'task': 'Создайте TCP-прокси: сервер, который принимает соединение от клиента и прозрачно проксирует все байты на другой удаленный сервер, возвращая ответ обратно (используйте `io.Copy` в двух горутинах для каждого соединения).', 'theory': 'Прозрачное проксирование трафика: связывание двух полнодуплексных сокетов через две горутины копирования `io.Copy(upstream, downstream)` и `io.Copy(downstream, upstream)`.', 'step_by_step': '1. Запустим Mock Upstream сервер.\n2. Запустим Transparent Proxy.\n3. Клиент отправляет запрос через прокси.\n4. Проверим получение корректного ответа от Upstream.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"io"\n\t"net"\n\t"sync"\n\t"time"\n)\n\nfunc handleProxy(client net.Conn, upstreamAddr string) {\n\tupstream, err := net.Dial("tcp", upstreamAddr)\n\tif err != nil {\n\t\tclient.Close()\n\t\treturn\n\t}\n\n\tvar once sync.Once\n\tcleanup := func() {\n\t\tonce.Do(func() {\n\t\t\tclient.Close()\n\t\t\tupstream.Close()\n\t\t})\n\t}\n\n\tgo func() {\n\t\t_, _ = io.Copy(upstream, client)\n\t\tcleanup()\n\t}()\n\n\tgo func() {\n\t\t_, _ = io.Copy(client, upstream)\n\t\tcleanup()\n\t}()\n}\n\nfunc main() {\n\t// 1. Upstream сервис\n\tupstream, _ := net.Listen("tcp", "127.0.0.1:0")\n\tdefer upstream.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tc, err := upstream.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo func(conn net.Conn) {\n\t\t\t\tdefer conn.Close()\n\t\t\t\tbuf := make([]byte, 128)\n\t\t\t\tn, _ := conn.Read(buf)\n\t\t\t\t_, _ = conn.Write([]byte("Upstream response to: " + string(buf[:n])))\n\t\t\t}(c)\n\t\t}\n\t}()\n\n\t// 2. Прокси сервис\n\tproxy, _ := net.Listen("tcp", "127.0.0.1:0")\n\tdefer proxy.Close()\n\n\tgo func() {\n\t\tfor {\n\t\t\tc, err := proxy.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo handleProxy(c, upstream.Addr().String())\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// 3. Клиент\n\tclient, _ := net.Dial("tcp", proxy.Addr().String())\n\tdefer client.Close()\n\n\t_, _ = client.Write([]byte("Query-A"))\n\tresp := make([]byte, 128)\n\tn, _ := client.Read(resp)\n\n\tfmt.Printf("[Transparent Proxy Result] %s\\n", string(resp[:n]))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Transparent Proxy Result] Upstream response to: Query-A'}], 'under_the_hood': '`io.Copy` блокируется до закрытия одной из сторон или возникновения ошибки сокета.', 'pitfalls': 'Если не вызвать `cleanup()` в обеих горутинах, разрыв соединения клиентом оставит висеть открытое соединение к апстриму.', 'bigtech_interview': '**Вопрос с собеседования:** «В чем отличие TCP Proxy (L4) от HTTP Proxy (L7 / Envoy / Nginx)?»\n**Ответ:** L4 прокси оперирует сырыми байтами TCP-потока без парсинга прикладных протоколов, обеспечивая максимальный throughput и минимальную задержку. L7 прокси парсит HTTP/gRPC заголовки, что дает возможности умной маршрутизации, ретраев и авторизации, но требует больше CPU/RAM.'}, {'num': 29, 'title': 'TCP-сервер с защитой от перегрузки на семафоре (Server Busy Reject)', 'task': 'Напиши **TCP-сервер с ограничением соединений** (semaphore): `sem := make(chan struct{}, 50)`. Каждое новое соединение захватывает слот. Если слотов нет — немедленно закрой `conn` с ошибкой `"server busy"`. ', 'theory': 'Паттерн Fast Reject (Защита от перегрузки / Backpressure): если лимит активных соединений исчерпан, сервер не ставит новые запросы в бесконечную очередь, а немедленно отправляет ответ `503 Service Unavailable / Server Busy` и сбрасывает соединение.', 'step_by_step': '1. Создадим семафор на 2 активных слота: `sem := make(chan struct{}, 2)`.\n2. При подключении пробуем захватить слот через неблокирующий `select default`.\n3. Если слот занят — пишем `ERR: SERVER_BUSY\\n` и закрываем сокет.\n4. Проверим сброс 3-го клиента.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"sync"\n\t"time"\n)\n\ntype LimitedServer struct {\n\tsem chan struct{}\n}\n\nfunc (s *LimitedServer) Handle(conn net.Conn) {\n\t// Неблокирующая проверка доступности слотов\n\tselect {\n\tcase s.sem <- struct{}{}:\n\t\t// Слот успешно захвачен\n\t\tdefer func() {\n\t\t\t<-s.sem\n\t\t\tconn.Close()\n\t\t}()\n\t\tfmt.Printf(" [+] Соединение %s принято в обработку.\\n", conn.RemoteAddr())\n\t\ttime.Sleep(50 * time.Millisecond) // Имитация работы\n\t\t_, _ = conn.Write([]byte("OK: PROCESSED\\n"))\n\n\tdefault:\n\t\t// Пул переполнен -> Fast Reject\n\t\tdefer conn.Close()\n\t\tfmt.Printf(" [!] ПЕРЕГРУЗКА: Отказ соединению %s (Server Busy)!\\n", conn.RemoteAddr())\n\t\t_, _ = conn.Write([]byte("ERR: SERVER_BUSY_TRY_LATER\\n"))\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tserver := &LimitedServer{sem: make(chan struct{}, 2)} // Всего 2 слота!\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo server.Handle(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\tvar wg sync.WaitGroup\n\twg.Add(3)\n\n\tfor i := 1; i <= 3; i++ {\n\t\tgo func(id int) {\n\t\t\tdefer wg.Done()\n\t\t\tconn, err := net.Dial("tcp", l.Addr().String())\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tdefer conn.Close()\n\n\t\t\tresp, _ := bufio.NewReader(conn).ReadString(\'\\n\')\n\t\t\tfmt.Printf(" [Client #%d Ответ] %s", id, resp)\n\t\t}(i)\n\t}\n\n\twg.Wait()\n\tfmt.Println("[Main] Тестирование механизма Fast Reject завершено.")\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n#  [+] Соединение 127.0.0.1:51234 принято в обработку.\n#  [+] Соединение 127.0.0.1:51235 принято в обработку.\n#  [!] ПЕРЕГРУЗКА: Отказ соединению 127.0.0.1:51236 (Server Busy)!\n#  [Client #3 Ответ] ERR: SERVER_BUSY_TRY_LATER\n#  [Client #1 Ответ] OK: PROCESSED\n#  [Client #2 Ответ] OK: PROCESSED\n# [Main] Тестирование механизма Fast Reject завершено.'}], 'under_the_hood': '`select default` проверяет готовность буфера канала за $O(1)$ без перевода горутины в состояние сна.', 'pitfalls': 'Не забывайте `conn.Close()` в ветке `default`, иначе отвергнутый клиент зависнет на чтении сокета.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему Fast Reject (сброс лишней нагрузки) лучше удержания клиентов в длинной очереди ожидания?»\n**Ответ:** Длинная очередь накапливает задержку (Latency Inflation), приводит к таймаутам на клиентах и повторным ретраям (Retry Storm), окончательно добивая перегруженный сервис. Fast Reject сохраняет работоспособность сервера для уже принятых запросов.'}, {'num': 30, 'title': 'UDP-клиент: отправка и прием независимых дейтаграмм', 'task': '**UDP-клиент**: Напиши клиента для упр. 330 через `net.DialUDP`. Обрати внимание, что в UDP нет потока, сообщения передаются отдельными датаграммами.', 'theory': 'Природа дейтаграмм UDP: каждый вызов `Write()` отправляет ровно один автономный IP-пакет (Datagram). Получатель читает пакет целиком одним вызовом `Read()`. Границы сообщений сохраняются аппаратно на уровне сетевого стека.', 'step_by_step': '1. Запустим UDP Echo сервер.\n2. Клиент отправляет 2 независимые дейтаграммы.\n3. Сервер считывает каждую дейтаграмму отдельным вызовом.\n4. Проверим сохранение границ сообщений.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"time"\n)\n\nfunc main() {\n\tserverAddr, _ := net.ResolveUDPAddr("udp", "127.0.0.1:0")\n\tserver, err := net.ListenUDP("udp", serverAddr)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer server.Close()\n\n\tactualAddr := server.LocalAddr().(*net.UDPAddr)\n\n\t// Сервер\n\tgo func() {\n\t\tbuf := make([]byte, 1024)\n\t\tfor {\n\t\t\tn, rAddr, err := server.ReadFromUDP(buf)\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tmsg := string(buf[:n])\n\t\t\t_, _ = server.WriteToUDP([]byte("ECHO: "+msg), rAddr)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// UDP Клиент\n\tclient, err := net.DialUDP("udp", nil, actualAddr)\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer client.Close()\n\n\tpackets := []string{"Datagram-1", "Datagram-2"}\n\tbuf := make([]byte, 1024)\n\n\tfor _, p := range packets {\n\t\t_, _ = client.Write([]byte(p))\n\t\tn, _ := client.Read(buf)\n\t\tfmt.Printf("[UDP Datagram Client] Отправлено: %s -> Получено: %s\\n", p, string(buf[:n]))\n\t}\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [UDP Datagram Client] Отправлено: Datagram-1 -> Получено: ECHO: Datagram-1\n# [UDP Datagram Client] Отправлено: Datagram-2 -> Получено: ECHO: Datagram-2'}], 'under_the_hood': 'UDP заголовок содержит поле `Length` (16 бит), определяющее точный размер дейтаграммы в байтах.', 'pitfalls': 'Если переданный в `Read()` буфер меньше размера пришедшей дейтаграммы, остаток байт будет безвозвратно отброшен ОС (Message Truncation).', 'bigtech_interview': '**Вопрос с собеседования:** «Почему в UDP невозможно частичное чтение пакета, как в TCP?»\n**Ответ:** UDP — протокол с сохранением границ сообщений (Message Boundary Preserving). Один вызов `recvfrom()` извлекает ровно одну дейтаграмму из очереди сокета целиком. Все не поместившиеся в буфер байты отсекаются с флагом `MSG_TRUNC`.'}, {'num': 31, 'title': 'Многопоточный сканер TCP-портов с семафором на 50 горутин', 'task': 'Напиши **TCP port scanner**: сканируй порты 1–1024 на `localhost`. Для каждого порта `net.DialTimeout("tcp", addr, 100ms)`. Выведи открытые порты. Ускорь через конкурентность ( semaphore на 50 горутин).', 'theory': 'Оптимизация сетевого сканирования: параллельный запуск сканирования сотен портов с пулом/семафором на 50 слотов сокращает суммарное время сканирования с десятков минут до нескольких секунд.', 'step_by_step': '1. Запустим тестовый TCP сервис на порту.\n2. Создадим семафор `sem := make(chan struct{}, 50)`.\n3. Запустим проверку диапазона портов.\n4. Выведем открытые порты.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"fmt"\n\t"net"\n\t"strconv"\n\t"sync"\n\t"time"\n)\n\nfunc main() {\n\t// Поднимаем тестовый сокет\n\tl, _ := net.Listen("tcp", "127.0.0.1:0")\n\tdefer l.Close()\n\n\t_, pStr, _ := net.SplitHostPort(l.Addr().String())\n\topenPort, _ := strconv.Atoi(pStr)\n\n\tfmt.Printf("[Scanner Setup] Открыт тестовый порт: %d\\n", openPort)\n\n\tconst maxWorkers = 50\n\tsem := make(chan struct{}, maxWorkers)\n\tvar wg sync.WaitGroup\n\n\tresults := make(chan int, 10)\n\n\tstartPort := openPort - 10\n\tendPort := openPort + 10\n\n\tstart := time.Now()\n\n\tfor port := startPort; port <= endPort; port++ {\n\t\twg.Add(1)\n\t\tsem <- struct{}{}\n\n\t\tgo func(p int) {\n\t\t\tdefer wg.Done()\n\t\t\tdefer func() { <-sem }()\n\n\t\t\ttarget := net.JoinHostPort("127.0.0.1", strconv.Itoa(p))\n\t\t\tconn, err := net.DialTimeout("tcp", target, 20*time.Millisecond)\n\t\t\tif err == nil {\n\t\t\t\tconn.Close()\n\t\t\t\tresults <- p\n\t\t\t}\n\t\t}(port)\n\t}\n\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(results)\n\t}()\n\n\tfor p := range results {\n\t\tfmt.Printf(" [+] ОБНАРУЖЕН ОТКРЫТЫЙ ПОРТ: 127.0.0.1:%d\\n", p)\n\t}\n\n\tfmt.Printf("[Scanner] Сканирование %d портов завершено за %v!\\n", \n\t\t(endPort - startPort + 1), time.Since(start).Round(time.Millisecond))\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Scanner Setup] Открыт тестовый порт: 58231\n#  [+] ОБНАРУЖЕН ОТКРЫТЫЙ ПОРТ: 127.0.0.1:58231\n# [Scanner] Сканирование 21 портов завершено за 22ms!'}], 'under_the_hood': 'Семафор предотвращает лавинообразное открытие файловых дескрипторов в таблице ядра ОС.', 'pitfalls': 'Всегда используйте `net.JoinHostPort` вместо конкатенации строк, чтобы корректно форматировать IPv6 адреса `[::1]:port`.', 'bigtech_interview': '**Вопрос с собеседования:** «Почему net.JoinHostPort("::1", "80") возвращает [::1]:80 с квадратными скобками?»\n**Ответ:** Квадратные скобки вокруг IPv6 адреса обязательны согласно RFC 3986, чтобы двоеточие в шестнадцатеричных группах адреса не конфликтовало с двоеточием перед номером порта.'}, {'num': 32, 'title': 'Сетевой широковещательный чат (TCP Broadcast Engine)', 'task': 'Реализуйте простой чат: сервер принимает сообщения от любого клиента и рассылает их всем остальным (broadcast).', 'theory': 'Широковещательная сеть: все подключенные сокеты регистрируются в пуле рассылки. Каждое полученное сообщение копируется во все сокеты, кроме сокета отправителя.', 'step_by_step': '1. Создадим структуру `SimpleChat`.\n2. Реализуем `Broadcast(sender, msg)`.\n3. Подключим Клиента А и Клиента Б.\n4. Проверим доставку сообщения.', 'code_blocks': [{'filename': 'main.go', 'lang': 'go', 'code': 'package main\n\nimport (\n\t"bufio"\n\t"fmt"\n\t"net"\n\t"sync"\n\t"time"\n)\n\ntype SimpleChat struct {\n\tmu    sync.Mutex\n\tconns map[net.Conn]struct{}\n}\n\nfunc (c *SimpleChat) Broadcast(sender net.Conn, msg string) {\n\tc.mu.Lock()\n\tdefer c.mu.Unlock()\n\n\tfor conn := range c.conns {\n\t\tif conn != sender {\n\t\t\t_, _ = conn.Write([]byte(msg + "\\n"))\n\t\t}\n\t}\n}\n\nfunc (c *SimpleChat) Handle(conn net.Conn) {\n\tc.mu.Lock()\n\tc.conns[conn] = struct{}{}\n\tc.mu.Unlock()\n\n\tdefer func() {\n\t\tc.mu.Lock()\n\t\tdelete(c.conns, conn)\n\t\tc.mu.Unlock()\n\t\tconn.Close()\n\t}()\n\n\tscanner := bufio.NewScanner(conn)\n\tfor scanner.Scan() {\n\t\tc.Broadcast(conn, scanner.Text())\n\t}\n}\n\nfunc main() {\n\tl, err := net.Listen("tcp", "127.0.0.1:0")\n\tif err != nil {\n\t\tpanic(err)\n\t}\n\tdefer l.Close()\n\n\tchat := &SimpleChat{conns: make(map[net.Conn]struct{})}\n\n\tgo func() {\n\t\tfor {\n\t\t\tconn, err := l.Accept()\n\t\t\tif err != nil {\n\t\t\t\treturn\n\t\t\t}\n\t\t\tgo chat.Handle(conn)\n\t\t}\n\t}()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент A\n\tcA, _ := net.Dial("tcp", l.Addr().String())\n\tdefer cA.Close()\n\n\t// Клиент B\n\tcB, _ := net.Dial("tcp", l.Addr().String())\n\tdefer cB.Close()\n\n\ttime.Sleep(10 * time.Millisecond)\n\n\t// Клиент A отправляет сообщение\n\t_, _ = cA.Write([]byte("Привет от Клиента А!\\n"))\n\n\t// Клиент B читает broadcast\n\tresp, _ := bufio.NewReader(cB).ReadString(\'\\n\')\n\tfmt.Printf("[Клиент B получил] %s", resp)\n}'}, {'filename': 'Терминал', 'lang': 'bash', 'code': 'go run main.go\n# Вывод:\n# [Клиент B получил] Привет от Клиента А!'}], 'under_the_hood': 'Запись в сокет `conn.Write` передает байты в системный выходной буфер сокета `SO_SNDBUF` ядра ОС.', 'pitfalls': 'В чатах с тысячами участников итерация по мапе под мьютексом заблокирует сервер. В HighLoad применяют каналы на каждого подписчика (Actor Model).', 'bigtech_interview': '**Вопрос с собеседования:** «Каков размер буферов сокетов по умолчанию в Linux (SO_RCVBUF / SO_SNDBUF)?»\n**Ответ:** По умолчанию ядро Linux динамически автотюнит размеры буферов (`tcp_rmem` и `tcp_wmem`) от 4 КБ до нескольких мегабайт в зависимости от полосы пропускания и сетевой задержки (BDP — Bandwidth Delay Product).'}]
